import React, { useState, useRef, useEffect } from 'react';
import { analyzeCreative, suggestNewCopys } from './services/geminiService';
import { AnalysisResult, AnalysisStatus, Brand, BRANDS } from './types';
import ResultDisplay from './components/ResultDisplay';
import TriggersModal from './components/TriggersModal';
import { 
  Sparkles, 
  AlertTriangle, 
  Loader2, 
  BrainCircuit, 
  Upload, 
  X, 
  Wand2, 
  BookOpen, 
  ChevronDown, 
  Check, 
  Globe, 
  PenTool, 
  Palette, 
  LogIn, 
  User, 
  ShieldCheck, 
  Zap, 
  ExternalLink,
  Lock
} from 'lucide-react';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean | null>(null);
  const [image, setImage] = useState<string | null>(null);
  const [mimeType, setMimeType] = useState<string>('');
  const [copyText, setCopyText] = useState('');
  const [context, setContext] = useState('');
  const [status, setStatus] = useState<AnalysisStatus>(AnalysisStatus.IDLE);
  const [result, setResult] = useState<AnalysisResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isSuggesting, setIsSuggesting] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isBrandMenuOpen, setIsBrandMenuOpen] = useState(false);
  const [selectedBrand, setSelectedBrand] = useState<Brand>('Anhanguera');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const brandMenuRef = useRef<HTMLDivElement>(null);

  // Check authentication on mount
  useEffect(() => {
    const checkAuth = async () => {
      try {
        if (window.aistudio) {
          const hasKey = await window.aistudio.hasSelectedApiKey();
          setIsAuthenticated(hasKey);
        } else {
          // Fallback if not in the expected environment, but normally this is true
          setIsAuthenticated(false);
        }
      } catch (e) {
        setIsAuthenticated(false);
      }
    };
    checkAuth();
  }, []);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (brandMenuRef.current && !brandMenuRef.current.contains(event.target as Node)) {
        setIsBrandMenuOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleLogin = async () => {
    try {
      if (window.aistudio) {
        await window.aistudio.openSelectKey();
        // As per instructions, assume success to avoid race conditions and proceed
        setIsAuthenticated(true);
      }
    } catch (err) {
      console.error("Erro ao conectar:", err);
      setError("Não foi possível abrir o seletor de conta Google.");
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (!file.type.startsWith('image/')) {
        setError("Por favor, selecione um arquivo de imagem válido.");
        return;
      }
      setMimeType(file.type);
      const reader = new FileReader();
      reader.onloadend = () => {
        setImage(reader.result as string);
        setError(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAnalyze = async () => {
    if (!image && !copyText) {
      setError("Forneça uma imagem ou um texto para análise.");
      return;
    }

    setStatus(AnalysisStatus.LOADING);
    setError(null);
    setResult(null);

    try {
      const data = await analyzeCreative(image, mimeType, copyText, context);
      setResult(data);
      setStatus(AnalysisStatus.SUCCESS);
    } catch (err: any) {
      console.error(err);
      // SPECIFIC RULE: Reset key selection if entity not found
      if (err.message?.includes("Requested entity was not found")) {
        setError("Sua sessão de API expirou ou o projeto foi removido. Por favor, conecte novamente.");
        setIsAuthenticated(false);
      } else {
        setError(err.message || "Ocorreu um erro inesperado na análise.");
      }
      setStatus(AnalysisStatus.ERROR);
    }
  };

  const handleGetSuggestions = async () => {
    if (!result || !copyText) return;
    setIsSuggesting(true);
    try {
      const { suggestions, sources } = await suggestNewCopys(result, copyText, context, selectedBrand);
      setResult({ ...result, suggestedCopys: suggestions, sources: sources });
    } catch (err: any) {
      console.error("Erro ao sugerir copys:", err);
      if (err.message?.includes("Requested entity was not found")) {
        setIsAuthenticated(false);
      }
    } finally {
      setIsSuggesting(false);
    }
  };

  const clearImage = () => {
    setImage(null);
    setMimeType('');
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  // Loading state for initial auth check
  if (isAuthenticated === null) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center">
        <div className="w-12 h-12 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin mb-4" />
        <p className="text-slate-400 font-medium animate-pulse">Verificando credenciais...</p>
      </div>
    );
  }

  // MANDATORY LOGIN SCREEN (Google Account Gate)
  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-[#f8fafc] flex items-center justify-center p-4 relative overflow-hidden">
        {/* Aesthetic background elements */}
        <div className="absolute top-0 -left-10 w-96 h-96 bg-indigo-100/50 rounded-full mix-blend-multiply filter blur-3xl opacity-70 animate-pulse" />
        <div className="absolute -bottom-10 -right-10 w-96 h-96 bg-emerald-100/50 rounded-full mix-blend-multiply filter blur-3xl opacity-70 animate-pulse delay-700" />

        <div className="bg-white/80 backdrop-blur-xl w-full max-w-lg rounded-[3rem] shadow-[0_32px_64px_-16px_rgba(0,0,0,0.1)] border border-white/50 p-8 md:p-14 relative z-10 animate-in fade-in zoom-in-95 duration-1000">
          <div className="flex flex-col items-center text-center">
            <div className="bg-indigo-600 p-5 rounded-[2rem] shadow-2xl shadow-indigo-200 mb-10 transform -rotate-6 hover:rotate-0 transition-transform duration-500">
              <Lock className="text-white w-10 h-10" />
            </div>

            <h1 className="text-4xl font-black text-slate-900 mb-4 tracking-tighter">
              Acesso <span className="text-indigo-600">Restrito</span>
            </h1>
            <p className="text-slate-500 font-medium mb-12 leading-relaxed">
              Para analisar seus criativos com precisão profissional, conecte-se com sua conta Google e utilize sua chave de API dedicada.
            </p>

            <div className="w-full space-y-4 mb-12">
              <div className="flex items-center gap-4 p-5 bg-white rounded-3xl border border-slate-100 shadow-sm text-left hover:border-indigo-200 transition-colors">
                <div className="bg-indigo-50 p-2.5 rounded-2xl">
                  <ShieldCheck className="w-5 h-5 text-indigo-600" />
                </div>
                <div>
                  <h4 className="text-xs font-bold text-slate-800 uppercase tracking-widest mb-0.5">Segurança Enterprise</h4>
                  <p className="text-[11px] text-slate-500 leading-tight">Conexão direta com Google Cloud Platform para máxima proteção de dados.</p>
                </div>
              </div>
              <div className="flex items-center gap-4 p-5 bg-white rounded-3xl border border-slate-100 shadow-sm text-left hover:border-emerald-200 transition-colors">
                <div className="bg-emerald-50 p-2.5 rounded-2xl">
                  <Zap className="w-5 h-5 text-emerald-600" />
                </div>
                <div>
                  <h4 className="text-xs font-bold text-slate-800 uppercase tracking-widest mb-0.5">Sua Própria Cota</h4>
                  <p className="text-[11px] text-slate-500 leading-tight">Utilize seus créditos do Google AI Studio sem limites de uso por este app.</p>
                </div>
              </div>
            </div>

            <button 
              onClick={handleLogin}
              className="w-full bg-slate-900 text-white py-5 rounded-[1.5rem] font-black text-sm uppercase tracking-[0.2em] hover:bg-indigo-600 transition-all shadow-2xl shadow-indigo-100 flex items-center justify-center gap-4 active:scale-[0.98] group"
            >
              <LogIn className="w-5 h-5 group-hover:translate-x-1 transition-transform" />
              Conectar com Google
            </button>

            <div className="mt-10 flex flex-col items-center gap-3">
              <a 
                href="https://ai.google.dev/gemini-api/docs/billing" 
                target="_blank" 
                rel="noopener noreferrer"
                className="text-[11px] font-bold text-slate-400 uppercase hover:text-indigo-600 transition-all flex items-center gap-2 decoration-indigo-200"
              >
                Configurar Faturamento (Billing)
                <ExternalLink className="w-3 h-3" />
              </a>
              <p className="text-[10px] text-slate-400 font-medium">Requer projeto ativo no Google Cloud</p>
            </div>
          </div>
        </div>
      </div>
    );
  }

  // MAIN APPLICATION INTERFACE (Rendered only after authentication)
  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 flex flex-col animate-in fade-in duration-700">
      <header className="bg-white/80 backdrop-blur-md border-b border-slate-200 sticky top-0 z-40 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 h-18 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-indigo-600 p-2 rounded-xl">
              <BrainCircuit className="text-white w-6 h-6" />
            </div>
            <h1 className="text-xl font-black tracking-tighter text-slate-900">Creative<span className="text-indigo-600">Vision</span></h1>
          </div>

          <div className="flex items-center gap-3 sm:gap-6">
            <button 
              onClick={() => setIsModalOpen(true)}
              className="flex items-center gap-2 px-3 py-2 text-slate-600 hover:bg-slate-50 rounded-xl transition-all font-bold text-xs uppercase tracking-widest"
            >
              <BookOpen className="w-4 h-4 text-indigo-600" />
              <span className="hidden md:inline">Gatilhos</span>
            </button>

            <div className="relative" ref={brandMenuRef}>
              <button 
                onClick={() => setIsBrandMenuOpen(!isBrandMenuOpen)}
                className={`flex items-center gap-2 px-4 py-2.5 rounded-xl transition-all font-bold text-[10px] uppercase tracking-[0.15em] border ${
                  isBrandMenuOpen 
                    ? 'bg-indigo-600 text-white border-indigo-600 shadow-xl shadow-indigo-100' 
                    : 'bg-indigo-50 text-indigo-700 border-indigo-100 hover:bg-indigo-100'
                }`}
              >
                <Globe className={`w-3.5 h-3.5 ${isBrandMenuOpen ? 'text-white' : 'text-indigo-600'}`} />
                <span>{selectedBrand}</span>
                <ChevronDown className={`w-3.5 h-3.5 transition-transform ${isBrandMenuOpen ? 'rotate-180' : ''}`} />
              </button>

              {isBrandMenuOpen && (
                <div className="absolute right-0 mt-2 w-60 bg-white border border-slate-100 rounded-3xl shadow-[0_20px_40px_rgba(0,0,0,0.1)] py-3 z-50 animate-in fade-in slide-in-from-top-2 duration-300">
                  <div className="px-5 py-2 border-b border-slate-50 mb-2">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Brand Voice</p>
                  </div>
                  {BRANDS.map(brand => (
                    <button
                      key={brand}
                      onClick={() => { setSelectedBrand(brand); setIsBrandMenuOpen(false); }}
                      className={`w-full px-5 py-2.5 text-left text-xs font-bold flex items-center justify-between hover:bg-slate-50 transition-colors ${
                        selectedBrand === brand ? 'text-indigo-600 bg-indigo-50/50' : 'text-slate-600'
                      }`}
                    >
                      {brand}
                      {selectedBrand === brand && <Check className="w-4 h-4" />}
                    </button>
                  ))}
                </div>
              )}
            </div>

            <div className="flex items-center gap-3 pl-4 border-l border-slate-100">
              <button 
                onClick={handleLogin}
                className="w-10 h-10 bg-white rounded-full flex items-center justify-center border-2 border-slate-100 hover:border-indigo-300 hover:bg-indigo-50 transition-all group"
                title="Trocar Chave / Reautenticar"
              >
                <User className="w-5 h-5 text-slate-400 group-hover:text-indigo-600" />
              </button>
            </div>
          </div>
        </div>
      </header>

      <main className="flex-grow max-w-7xl mx-auto w-full px-4 py-8 md:py-16">
        <div className="grid grid-cols-1 xl:grid-cols-12 gap-12">

          <div className="xl:col-span-5 space-y-8">
            <div className="space-y-8">
              <div className="bg-white rounded-[2.5rem] p-8 shadow-sm border border-slate-200 relative group hover:shadow-md transition-shadow">
                <div className="flex items-center gap-3 mb-8">
                  <div className="bg-amber-100 p-3 rounded-2xl">
                    <PenTool className="text-amber-600 w-5 h-5" />
                  </div>
                  <h2 className="text-xl font-bold text-slate-800 tracking-tight">Redação Criativa</h2>
                </div>

                <div className="mb-4">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-3 block px-1">Texto da Peça</label>
                  <textarea
                    className="w-full bg-slate-50 border border-slate-200 rounded-3xl p-6 text-slate-800 focus:ring-4 focus:ring-amber-500/10 focus:border-amber-500 outline-none transition-all min-h-[160px] text-sm leading-relaxed"
                    placeholder="Cole o corpo do anúncio ou copy da peça..."
                    value={copyText}
                    onChange={(e) => setCopyText(e.target.value)}
                  />
                </div>
              </div>

              <div className="bg-white rounded-[2.5rem] p-8 shadow-sm border border-slate-200 relative group hover:shadow-md transition-shadow">
                <div className="flex items-center gap-3 mb-8">
                  <div className="bg-indigo-100 p-3 rounded-2xl">
                    <Palette className="text-indigo-600 w-5 h-5" />
                  </div>
                  <h2 className="text-xl font-bold text-slate-800 tracking-tight">Identidade Visual</h2>
                </div>

                <input type="file" ref={fileInputRef} onChange={handleFileChange} accept="image/*" className="hidden" />
                {!image ? (
                  <div onClick={() => fileInputRef.current?.click()} className="w-full h-48 border-4 border-dashed border-slate-100 rounded-[2rem] flex flex-col items-center justify-center gap-4 cursor-pointer hover:border-indigo-400 hover:bg-indigo-50/50 transition-all group">
                    <div className="bg-slate-50 p-4 rounded-full group-hover:scale-110 transition-transform">
                      <Upload className="w-8 h-8 text-slate-300 group-hover:text-indigo-600" />
                    </div>
                    <p className="text-xs font-black text-slate-400 uppercase tracking-widest">Subir Layout da Peça</p>
                  </div>
                ) : (
                  <div className="relative w-full rounded-3xl overflow-hidden border-2 border-slate-100 group">
                    <img src={image} alt="Preview" className="w-full h-auto object-contain max-h-[300px] mx-auto bg-slate-50" />
                    <div className="absolute inset-0 bg-slate-900/0 group-hover:bg-slate-900/40 transition-all flex items-center justify-center opacity-0 group-hover:opacity-100">
                       <button onClick={clearImage} className="bg-red-500 text-white p-3 rounded-full hover:scale-110 transition-transform shadow-xl">
                          <X className="w-5 h-5" />
                       </button>
                    </div>
                  </div>
                )}
              </div>

              <div className="bg-white rounded-[2.5rem] p-8 shadow-sm border border-slate-200">
                <div className="mb-8">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-3 block px-1">Meta-Informação</label>
                  <input
                    type="text"
                    className="w-full bg-slate-50 border border-slate-200 rounded-2xl p-4 text-sm outline-none focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 transition-all"
                    placeholder="Ex: Story Instagram, Banner GDN, Briefing..."
                    value={context}
                    onChange={(e) => setContext(e.target.value)}
                  />
                </div>

                {error && (
                  <div className="mb-8 p-5 bg-red-50 border border-red-100 rounded-3xl flex items-start gap-4 text-red-600 text-sm animate-in shake duration-500">
                    <AlertTriangle className="w-6 h-6 flex-shrink-0" />
                    <p className="font-medium">{error}</p>
                  </div>
                )}

                <div className="space-y-4">
                  <button
                    onClick={handleAnalyze}
                    disabled={status === AnalysisStatus.LOADING || (!image && !copyText)}
                    className={`w-full py-5 rounded-[1.5rem] font-black text-xs uppercase tracking-[0.2em] flex items-center justify-center gap-3 transition-all shadow-xl active:scale-95 ${
                      status === AnalysisStatus.LOADING || (!image && !copyText)
                      ? 'bg-slate-100 text-slate-400 cursor-not-allowed' 
                      : 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-indigo-100'
                    }`}
                  >
                    {status === AnalysisStatus.LOADING ? (
                      <><Loader2 className="w-5 h-5 animate-spin" /> Processando...</>
                    ) : (
                      <><Sparkles className="w-5 h-5" /> Gerar Diagnóstico</>
                    )}
                  </button>

                  {status === AnalysisStatus.SUCCESS && result && !result.suggestedCopys && (
                    <button
                      onClick={handleGetSuggestions}
                      disabled={isSuggesting}
                      className="w-full py-4 rounded-[1.5rem] border-2 border-indigo-600 text-indigo-600 font-black text-xs uppercase tracking-[0.2em] flex items-center justify-center gap-3 hover:bg-indigo-50 transition-all"
                    >
                      {isSuggesting ? (
                        <><Loader2 className="w-4 h-4 animate-spin" /> Otimizando...</>
                      ) : (
                        <><Wand2 className="w-4 h-4" /> Refinar Copy para {selectedBrand}</>
                      )}
                    </button>
                  )}
                </div>
              </div>
            </div>
          </div>

          <div className="xl:col-span-7">
            {status === AnalysisStatus.IDLE && (
              <div className="h-full min-h-[500px] flex flex-col items-center justify-center text-center p-12 bg-white/40 rounded-[3rem] border-4 border-dashed border-slate-200/60">
                <div className="bg-white p-6 rounded-[2rem] shadow-xl shadow-slate-200/50 mb-8">
                  <BrainCircuit className="w-16 h-16 text-indigo-200" />
                </div>
                <h3 className="text-2xl font-black text-slate-300 tracking-tight">IA pronta para análise</h3>
                <p className="text-slate-400 max-w-sm mt-4 text-sm leading-relaxed">Insira o texto e o layout para que possamos extrair os gatilhos e atributos de performance.</p>
              </div>
            )}

            {status === AnalysisStatus.LOADING && (
              <div className="h-full flex flex-col items-center justify-center text-center p-12">
                <div className="relative mb-10">
                  <div className="w-24 h-24 border-8 border-slate-100 border-t-indigo-600 rounded-full animate-spin"></div>
                  <div className="absolute inset-0 flex items-center justify-center">
                    <BrainCircuit className="w-8 h-8 text-indigo-600 animate-pulse" />
                  </div>
                </div>
                <h3 className="text-2xl font-black text-slate-800 tracking-tight">Decodificando Criativo</h3>
                <p className="text-slate-500 text-sm mt-3 font-medium">Extraindo semântica e hierarquia visual...</p>
              </div>
            )}

            {status === AnalysisStatus.SUCCESS && result && (
              <ResultDisplay data={result} />
            )}
          </div>
        </div>
      </main>

      <footer className="py-8 border-t border-slate-200 text-center">
        <p className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.3em]">CreativeVision AI • Powered by Gemini Flash 3.0</p>
      </footer>

      <TriggersModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} />
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { analyzeCreative, suggestNewCopys } from './services/geminiService';
import { AnalysisResult, AnalysisStatus, Brand, BRANDS } from './types';
import ResultDisplay from './components/ResultDisplay';
import TriggersModal from './components/TriggersModal';
import { 
  Sparkles, 
  AlertTriangle, 
  Loader2, 
  BrainCircuit, 
  Upload, 
  X, 
  Wand2, 
  BookOpen, 
  ChevronDown, 
  Check, 
  Globe, 
  PenTool, 
  Palette, 
  LogIn, 
  User, 
  ShieldCheck, 
  Zap, 
  ExternalLink,
  Lock
} from 'lucide-react';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean | null>(null);
  const [image, setImage] = useState<string | null>(null);
  const [mimeType, setMimeType] = useState<string>('');
  const [copyText, setCopyText] = useState('');
  const [context, setContext] = useState('');
  const [status, setStatus] = useState<AnalysisStatus>(AnalysisStatus.IDLE);
  const [result, setResult] = useState<AnalysisResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isSuggesting, setIsSuggesting] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isBrandMenuOpen, setIsBrandMenuOpen] = useState(false);
  const [selectedBrand, setSelectedBrand] = useState<Brand>('Anhanguera');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const brandMenuRef = useRef<HTMLDivElement>(null);

  // Verifica autenticação inicial
  useEffect(() => {
    const checkAuth = async () => {
      try {
        if (window.aistudio) {
          const hasKey = await window.aistudio.hasSelectedApiKey();
          setIsAuthenticated(hasKey);
        } else {
          setIsAuthenticated(false);
        }
      } catch (e) {
        setIsAuthenticated(false);
      }
    };
    checkAuth();
  }, []);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (brandMenuRef.current && !brandMenuRef.current.contains(event.target as Node)) {
        setIsBrandMenuOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleLogin = async () => {
    try {
      if (window.aistudio) {
        await window.aistudio.openSelectKey();
        // Assume sucesso imediato para evitar condições de corrida
        setIsAuthenticated(true);
      }
    } catch (err) {
      console.error("Erro ao conectar:", err);
      setError("Não foi possível conectar com sua conta Google.");
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (!file.type.startsWith('image/')) {
        setError("Por favor, selecione um arquivo de imagem válido.");
        return;
      }
      setMimeType(file.type);
      const reader = new FileReader();
      reader.onloadend = () => {
        setImage(reader.result as string);
        setError(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAnalyze = async () => {
    if (!image && !copyText) {
      setError("Forneça uma imagem ou um texto para análise.");
      return;
    }

    setStatus(AnalysisStatus.LOADING);
    setError(null);
    setResult(null);

    try {
      const data = await analyzeCreative(image, mimeType, copyText, context);
      setResult(data);
      setStatus(AnalysisStatus.SUCCESS);
    } catch (err: any) {
      console.error(err);
      // Se a chave for inválida ou não encontrada, reseta autenticação
      if (err.message?.includes("Requested entity was not found")) {
        setError("Sua sessão de API expirou ou a chave é inválida. Por favor, conecte novamente.");
        setIsAuthenticated(false);
      } else {
        setError(err.message || "Ocorreu um erro inesperado.");
      }
      setStatus(AnalysisStatus.ERROR);
    }
  };

  const handleGetSuggestions = async () => {
    if (!result || !copyText) return;
    setIsSuggesting(true);
    try {
      const { suggestions, sources } = await suggestNewCopys(result, copyText, context, selectedBrand);
      setResult({ ...result, suggestedCopys: suggestions, sources: sources });
    } catch (err: any) {
