import { AnalysisResult, SuggestedCopy, GroundingSource, Brand } from "../types";

const KNOWLEDGE_BASE_PROMPT = `
Você é um especialista em análise de peças publicitárias e redação (copywriting). 
Sua análise deve ser baseada ESTRITAMENTE na seguinte taxonomia da planilha oficial:

CATEGORIA: Atributo
- Prova Social: Muitas pessoas já fizeram e deu certo.
- Autoridade: Validação por instituições, especialistas ou dados oficiais.
- Resultados Concretos: Métricas claras: emprego, salário, aprovação, crescimento.
- Casos Reais: Histórias objetivas de pessoas semelhantes ao público.
- Eficiência: Menos tempo, menos esforço, mais resultado.
- Credibilidade: Tradição, reputação e histórico confiável.
- Segurança: Estabilidade, regulamentação, estrutura sólida.
- Qualidade Percebida: Sensação de algo bem feito e profissional.
- Pertencimento: Fazer parte de algo maior ou reconhecido.
- Identificação: Linguagem, estética e valores próximos do público.
- Confiabilidade: Cumpre o que promete, sem surpresas.
- Clareza: Comunicação simples, objetiva e transparente.
- Humanização: Mostra pessoas reais, empatia e proximidade.

CATEGORIA: Atributo + Performance
- Status: Valorização social ou profissional indireta.
- Diferenciação: Característica única que foge do padrão.
- Validação Externa: Reconhecimento pelo mercado ou órgãos reguladores.

CATEGORIA: Oferta
- Ancoragem de Preço: Comparação com preço anterior ou valor “real” maior.
- Inclusão: Bolsas de até 100% para estudar.
- Acessibilidade Financeira: Mostra que “cabe no bolso” (parcelas, valores baixos).
- Benefício Extra: Algo a mais sem custo (isenção, bônus, vantagem).

CATEGORIA: Oferta + Performance
- Custo de Oportunidade: Destaca o que a pessoa perde ao não agir agora.

CATEGORIA: Oferta + Atributo
- Autonomia e Inclusão: Bolsas de até 100% para estudar de onde e como quiser.

CATEGORIA: Performance
- Escassez: Poucas vagas, tempo limitado ou benefício que acaba logo.
- FOMO: Aversão à perda.
- Urgência: Pressão temporal clara para decisão imediata.
- Facilidade: Processo simples, sem burocracia ou esforço.
- Exclusividade: Oferta válida apenas para um grupo específico.
- Previsibilidade: Caminho claro do início ao resultado final.
- Comparativo de Performance: Mostra desempenho superior frente à média do mercado.

CATEGORIA: Performance + Atributo
- Risco Zero: Garantias, cancelamento fácil, sem compromisso inicial.
- Comparação Direta: Mostra que a oferta é melhor que alternativas comuns.
- Consistência: Resultados repetidos ao longo do tempo.

CATEGORIA: Performance + Oferta
- Evidência Numérica: Percentuais, rankings, volumes, tempo médio.
`;

const getBrandSpecificContext = (brand: Brand) => {
  switch (brand) {
    case 'Anhanguera': return "sites oficiais anhanguera.com e blog.anhanguera.com";
    case 'Unopar': return "site oficial unopar.com.br";
    case 'Unime': return "site oficial unime.edu.br";
    case 'Pitágoras': return "site oficial pitagoras.com.br";
    case 'Unic': return "site oficial unic.com.br";
    case 'Uniderp': return "site oficial uniderp.com.br";
    case 'Anglo': return "site oficial portalanglo.com.br";
    case 'Singularidades': return "site oficial singularidades.com.br";
    case 'Red Balloon': return "site oficial redballoon.com.br";
    default: return `site oficial da marca ${brand}`;
  }
};

export const analyzeCreative = async (
  base64Image: string | null, 
  mimeType: string, 
  copyText: string, 
  contextText?: string
): Promise<AnalysisResult> => {
  // Instancia o SDK com a chave fornecida pelo seletor de conta do usuário
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const parts: any[] = [
    { text: `${KNOWLEDGE_BASE_PROMPT}

Analise a peça (Imagem e/ou Texto da Copy). 
Sua tarefa é extrair os 2 pilares (gatilhos/atributos) mais fortes de acordo com a planilha.

Texto da Copy: "${copyText}"
Contexto Adicional: "${contextText || 'Nenhum'}"` }
  ];

  if (base64Image) {
    parts.push({
      inlineData: {
        data: base64Image.split(',')[1],
        mimeType: mimeType,
      },
    });
  }

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: { parts },
    config: {
      temperature: 0.1,
      seed: 42,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          score: { type: Type.NUMBER },
          summary: { type: Type.STRING },
          foundItems: {
            type: Type.ARRAY,
            minItems: 2,
            maxItems: 2,
            items: {
              type: Type.OBJECT,
              properties: {
                category: { type: Type.STRING },
                name: { type: Type.STRING },
                intensity: { type: Type.NUMBER },
                officialDescription: { type: Type.STRING },
                analysis: { type: Type.STRING },
                evidence: { type: Type.STRING }
              },
              required: ["category", "name", "intensity", "officialDescription", "analysis", "evidence"]
            }
          },
          improvements: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          }
        },
        required: ["score", "summary", "foundItems", "improvements"]
      }
    }
  });

  const resultText = response.text;
  if (!resultText) throw new Error("Falha na resposta da IA.");

  return JSON.parse(resultText) as AnalysisResult;
};

export const suggestNewCopys = async (
  originalAnalysis: AnalysisResult,
  originalCopy: string,
  context: string,
  brand: Brand
): Promise<{ suggestions: SuggestedCopy[], sources: GroundingSource[] }> => {
  // Instancia o SDK com a chave fornecida pelo seletor de conta do usuário
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const detectedPillars = originalAnalysis.foundItems.map(i => `${i.name} (${i.category})`).join(", ");
  const brandKnowledgeBase = getBrandSpecificContext(brand);

  const prompt = `${KNOWLEDGE_BASE_PROMPT}

CONTEXTO DE MARCA OBRIGATÓRIO:
Utilize como base de conhecimento as diretrizes e o tom de voz da marca: ${brand}.
Consulte prioritariamente o ${brandKnowledgeBase}.

Instrução:
Com base no texto original fornecido ("${originalCopy}"), sugira 3 novas variações que FORTALEÇAM e OTIMIZEM os gatilhos/atributos já identificados na análise: ${detectedPillars}.

O objetivo é tornar o texto mais adequado ao pilar identificado, elevando a percepção da categoria e do gatilho para o público, respeitando rigorosamente o tom de voz de ${brand}.

Copy original: "${originalCopy}"
Contexto do usuário: "${context}"

IMPORTANTE: Retorne APENAS um objeto JSON puro contendo um array "suggestions" com os campos: trigger, category, text, reasoning.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      temperature: 0.2,
      seed: 42,
      tools: [{ googleSearch: {} }]
    }
  });

  const responseText = response.text || "";
  const jsonMatch = responseText.match(/\{[\s\S]*\}/);
  const jsonStr = jsonMatch ? jsonMatch[0] : responseText;

  let suggestions: SuggestedCopy[] = [];
  try {
    const parsed = JSON.parse(jsonStr);
    suggestions = Array.isArray(parsed.suggestions) ? parsed.suggestions : (Array.isArray(parsed) ? parsed : []);
  } catch (e) {
    console.error("Erro ao parsear JSON de sugestões:", e, responseText);
  }

  const sources: GroundingSource[] = [];
  const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
  if (chunks) {
    chunks.forEach((chunk: any) => {
      if (chunk.web?.uri) {
        sources.push({
          title: chunk.web.title || `Referência ${brand}`,
          uri: chunk.web.uri
        });
      }
    });
  }

  return { suggestions, sources };
};

