  const [result, setResult] = useState<AnalysisResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isSuggesting, setIsSuggesting] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isBrandMenuOpen, setIsBrandMenuOpen] = useState(false);
  const [selectedBrand, setSelectedBrand] = useState<Brand>('Anhanguera');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const brandMenuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const checkAuth = async () => {
      try {
        if (window.aistudio) {
          const hasKey = await window.aistudio.hasSelectedApiKey();
          setIsAuthenticated(hasKey);
        } else {
          setIsAuthenticated(false);
        }
      } catch (e) {
        setIsAuthenticated(false);
      }
    };
    checkAuth();
  }, []);

  const handleGoogleLogin = async () => {
    try {
      if (window.aistudio) {
        // O openSelectKey funciona como o seletor de login do Google para o Gemini
        await window.aistudio.openSelectKey();
        // Após o login, assumimos sucesso conforme diretrizes para fluidez
        setIsAuthenticated(true);
        setError(null);
      }
    } catch (err) {
      console.error("Login error:", err);
      setError("Não foi possível completar o login com o Google.");
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (!file.type.startsWith('image/')) {
        setError("Por favor, selecione uma imagem.");
        return;
      }
      setMimeType(file.type);
      const reader = new FileReader();
      reader.onloadend = () => {
        setImage(reader.result as string);
        setError(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAnalyze = async () => {
    if (!image && !copyText) {
      setError("Insira pelo menos um texto ou uma imagem para análise.");
      return;
    }

    setStatus(AnalysisStatus.LOADING);
    setError(null);
    setResult(null);

    try {
      const data = await analyzeCreative(image, mimeType, copyText, context);
      setResult(data);
      setStatus(AnalysisStatus.SUCCESS);
    } catch (err: any) {
      console.error(err);
      if (err.message?.includes("Requested entity was not found")) {
        setError("Sua sessão expirou. Por favor, faça login novamente.");
        setIsAuthenticated(false);
      } else {
        setError(err.message || "Erro ao processar com seu Gemini.");
      }
      setStatus(AnalysisStatus.ERROR);
    }
  };

  const handleGetSuggestions = async () => {
    if (!result || !copyText) return;
    setIsSuggesting(true);
    try {
      const { suggestions, sources } = await suggestNewCopys(result, copyText, context, selectedBrand);
      setResult({ ...result, suggestedCopys: suggestions, sources: sources });
    } catch (err: any) {
      if (err.message?.includes("Requested entity was not found")) {
        setIsAuthenticated(false);
      }
    } finally {
      setIsSuggesting(false);
    }
  };

