               </svg>
            </div>
            <span className="font-bold text-slate-700">Entrar com Google</span>
          </button>

          <div className="mt-10 flex flex-col gap-3">
             <div className="flex items-center gap-2 justify-center text-[10px] text-slate-400 font-bold uppercase tracking-widest">
                <ShieldCheck className="w-3 h-3" />
                Seus dados protegidos pelo Google
             </div>
             <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" className="text-[10px] text-indigo-500 font-bold hover:underline">Ver informações de faturamento e cotas</a>
          </div>
        </div>
      </div>
    );
