                    <button onClick={clearImage} className="absolute top-2 right-2 p-1.5 bg-white/90 backdrop-blur-sm text-red-500 rounded-full shadow-sm">
                      <X className="w-3 h-3" />
                    </button>
                  </div>
                )}
              </div>

              <div className="pt-6 border-t border-slate-50">
                {error && (
                  <div className="mb-4 p-4 bg-red-50 text-red-600 rounded-xl text-xs font-bold flex items-center gap-2">
                    <AlertTriangle className="w-4 h-4" />
                    {error}
                  </div>
                )}

                <button
                  onClick={handleAnalyze}
                  disabled={status === AnalysisStatus.LOADING || (!image && !copyText)}
                  className={`w-full py-4 rounded-2xl font-black text-xs uppercase tracking-widest flex items-center justify-center gap-2 transition-all active:scale-95 ${
                    status === AnalysisStatus.LOADING || (!image && !copyText)
                    ? 'bg-slate-100 text-slate-400 cursor-not-allowed' 
                    : 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-lg shadow-indigo-100'
                  }`}
                >
                  {status === AnalysisStatus.LOADING ? (
                    <><Loader2 className="w-4 h-4 animate-spin" /> Analisando...</>
                  ) : (
                    <><Sparkles className="w-4 h-4" /> Analisar Criativo</>
                  )}
                </button>

                {status === AnalysisStatus.SUCCESS && result && !result.suggestedCopys && (
                  <button
                    onClick={handleGetSuggestions}
                    disabled={isSuggesting}
                    className="w-full mt-3 py-3 rounded-2xl border-2 border-indigo-600 text-indigo-600 font-black text-xs uppercase tracking-widest flex items-center justify-center gap-2 hover:bg-indigo-50 transition-all"
                  >
                    {isSuggesting ? (
                      <><Loader2 className="w-4 h-4 animate-spin" /> Otimizando...</>
                    ) : (
                      <><Wand2 className="w-4 h-4" /> Sugerir Melhorias</>
                    )}
                  </button>
                )}
              </div>
            </div>
          </div>

          <div className="xl:col-span-7">
            {status === AnalysisStatus.IDLE && (
              <div className="h-full min-h-[400px] flex flex-col items-center justify-center text-center p-8 bg-white/50 rounded-[2rem] border-2 border-dashed border-slate-100">
                <BrainCircuit className="w-10 h-10 text-slate-200 mb-4" />
                <h3 className="text-xl font-bold text-slate-300">Aguardando análise</h3>
              </div>
            )}

            {status === AnalysisStatus.LOADING && (
              <div className="h-full flex flex-col items-center justify-center text-center p-8">
                <Loader2 className="w-10 h-10 text-indigo-600 animate-spin mb-4" />
                <p className="text-slate-500 font-medium">Usando seu Gemini para decodificar a peça...</p>
              </div>
            )}

            {status === AnalysisStatus.SUCCESS && result && (
              <ResultDisplay data={result} />
            )}
          </div>
        </div>
      </main>

      <TriggersModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} />
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { analyzeCreative, suggestNewCopys } from './services/geminiService';
import { AnalysisResult, AnalysisStatus, Brand, BRANDS } from './types';
import ResultDisplay from './components/ResultDisplay';
import TriggersModal from './components/TriggersModal';
import { 
  Sparkles, 
  AlertTriangle, 
  Loader2, 
  BrainCircuit, 
  Upload, 
  X, 
  Wand2, 
  BookOpen, 
  ChevronDown, 
  Check, 
  Globe, 
  PenTool, 
  Palette, 
  LogIn, 
  User, 
  ShieldCheck, 
  Zap, 
  ExternalLink,
  Lock,
  ArrowRight
} from 'lucide-react';

declare global {
  interface Window {
    aistudio: {
      hasSelectedApiKey: () => Promise<boolean>;
      openSelectKey: () => Promise<void>;
    };
  }
}

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean | null>(null);
  const [image, setImage] = useState<string | null>(null);
  const [mimeType, setMimeType] = useState<string>('');
  const [copyText, setCopyText] = useState('');
  const [context, setContext] = useState('');
  const [status, setStatus] = useState<AnalysisStatus>(AnalysisStatus.IDLE);
  const [result, setResult] = useState<AnalysisResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isSuggesting, setIsSuggesting] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isBrandMenuOpen, setIsBrandMenuOpen] = useState(false);
  const [selectedBrand, setSelectedBrand] = useState<Brand>('Anhanguera');
  const [isLoggingIn, setIsLoggingIn] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const brandMenuRef = useRef<HTMLDivElement>(null);

  // Inicialização e verificação de chave existente
  useEffect(() => {
    const checkAuth = async () => {
      try {
        // Aguarda um pequeno delay para garantir que o script global aistudio esteja pronto
        if (window.aistudio) {
          const hasKey = await window.aistudio.hasSelectedApiKey();
          setIsAuthenticated(hasKey);
        } else {
          // Se não houver aistudio, pode ser um ambiente sem suporte ao seletor
          setIsAuthenticated(false);
        }
      } catch (e) {
        console.error("Erro ao verificar autenticação:", e);
        setIsAuthenticated(false);
      }
    };
    checkAuth();
  }, []);

  const handleGoogleLogin = async () => {
    setError(null);
    setIsLoggingIn(true);
    try {
      if (window.aistudio) {
        await window.aistudio.openSelectKey();
        // Conforme instrução: assumir sucesso imediato após disparar o seletor
        setIsAuthenticated(true);
      } else {
        throw new Error("O serviço de autenticação Google AI Studio não está disponível neste ambiente.");
      }
    } catch (err: any) {
      console.error("Login error:", err);
      setError(err.message || "Não foi possível completar o login com o Google.");
      setIsAuthenticated(false);
    } finally {
      setIsLoggingIn(false);
    }
