import ResultDisplay from './components/ResultDisplay';
import TriggersModal from './components/TriggersModal';
import { 
  Sparkles, 
  AlertTriangle, 
  Loader2, 
  BrainCircuit, 
  Upload, 
  X, 
  Wand2, 
  BookOpen, 
  ChevronDown, 
  Check, 
  Globe, 
  PenTool, 
  Palette, 
  LogIn, 
  User, 
  ShieldCheck, 
  Zap, 
  ExternalLink,
  Lock,
  ArrowRight
} from 'lucide-react';

// Removed manual Window interface declaration as it conflicts with the environment's pre-defined AIStudio type.

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean | null>(null);
  const [image, setImage] = useState<string | null>(null);
  const [mimeType, setMimeType] = useState<string>('');
  const [copyText, setCopyText] = useState('');
  const [context, setContext] = useState('');
  const [status, setStatus] = useState<AnalysisStatus>(AnalysisStatus.IDLE);
  const [result, setResult] = useState<AnalysisResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isSuggesting, setIsSuggesting] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isBrandMenuOpen, setIsBrandMenuOpen] = useState(false);
  const [selectedBrand, setSelectedBrand] = useState<Brand>('Anhanguera');
  const [isLoggingIn, setIsLoggingIn] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const brandMenuRef = useRef<HTMLDivElement>(null);

  // Inicialização e verificação de chave existente
  useEffect(() => {
    const checkAuth = async () => {
      try {
        // Aguarda um pequeno delay para garantir que o script global aistudio esteja pronto
        // @ts-ignore - aistudio is provided by the environment
        if (window.aistudio) {
          // @ts-ignore
          const hasKey = await window.aistudio.hasSelectedApiKey();
          setIsAuthenticated(hasKey);
        } else {
          // Se não houver aistudio, pode ser um ambiente sem suporte ao seletor
          setIsAuthenticated(false);
        }
      } catch (e) {
        console.error("Erro ao verificar autenticação:", e);
        setIsAuthenticated(false);
      }
    };
    checkAuth();
  }, []);

  const handleGoogleLogin = async () => {
    setError(null);
    setIsLoggingIn(true);
    try {
      // @ts-ignore
      if (window.aistudio) {
        // @ts-ignore
        await window.aistudio.openSelectKey();
        // Conforme instrução: assumir sucesso imediato após disparar o seletor
        setIsAuthenticated(true);
      } else {
        throw new Error("O serviço de autenticação Google AI Studio não está disponível neste ambiente.");
      }
    } catch (err: any) {
      console.error("Login error:", err);
      setError(err.message || "Não foi possível completar o login com o Google.");
      setIsAuthenticated(false);
    } finally {
      setIsLoggingIn(false);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (!file.type.startsWith('image/')) {
        setError("Por favor, selecione uma imagem.");
        return;
      }
      setMimeType(file.type);
      const reader = new FileReader();
      reader.onloadend = () => {
        setImage(reader.result as string);
        setError(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAnalyze = async () => {
    if (!image && !copyText) {
      setError("Insira pelo menos um texto ou uma imagem para análise.");
      return;
    }

    setStatus(AnalysisStatus.LOADING);
    setError(null);
    setResult(null);

    try {
      const data = await analyzeCreative(image, mimeType, copyText, context);
      setResult(data);
      setStatus(AnalysisStatus.SUCCESS);
    } catch (err: any) {
      console.error("Análise falhou:", err);
      // Tratamento de expiração de chave ou erro de entidade não encontrada
      if (err.message?.includes("Requested entity was not found")) {
        setError("Sua sessão do Google API expirou ou o projeto foi desconectado. Por favor, entre novamente.");
        setIsAuthenticated(false);
      } else {
        setError(err.message || "Ocorreu um erro ao processar com seu Gemini. Verifique sua conexão ou cotas.");
      }
      setStatus(AnalysisStatus.ERROR);
    }
  };

  const handleGetSuggestions = async () => {
    if (!result || !copyText) return;
    setIsSuggesting(true);
    try {
      const { suggestions, sources } = await suggestNewCopys(result, copyText, context, selectedBrand);
      setResult({ ...result, suggestedCopys: suggestions, sources: sources });
    } catch (err: any) {
      if (err.message?.includes("Requested entity was not found")) {
        setIsAuthenticated(false);
      }
    } finally {
      setIsSuggesting(false);
    }
  };

  const clearImage = () => {
