                  </svg>
                </div>
                <span className="font-black text-xs uppercase tracking-[0.2em]">Entrar com Google</span>
              </>
            )}
          </button>

          {error && (
            <div className="mt-6 p-4 bg-red-50 text-red-600 rounded-2xl text-[11px] font-bold flex items-center gap-2 animate-in slide-in-from-top-2">
              <AlertTriangle className="w-4 h-4 flex-shrink-0" />
              <p>{error}</p>
            </div>
          )}

          <div className="mt-10 flex flex-col gap-4">
             <div className="flex items-center gap-2 justify-center text-[10px] text-slate-400 font-bold uppercase tracking-widest">
                <ShieldCheck className="w-3.5 h-3.5" />
                Sua chave fica protegida pelo Google
             </div>
             <div className="border-t border-slate-100 pt-4">
               <a 
                 href="https://ai.google.dev/gemini-api/docs/billing" 
                 target="_blank" 
                 rel="noopener noreferrer"
                 className="text-[10px] text-indigo-500 font-black hover:text-slate-900 transition-colors uppercase tracking-widest flex items-center justify-center gap-1.5"
               >
                 Documentação de Faturamento e Cotas
                 <ExternalLink className="w-3 h-3" />
               </a>
             </div>
          </div>
        </div>
      </div>
    );
  }

  return (
