                  </svg>
                </div>
                <span className="font-bold text-slate-700">Entrar com Google</span>
              </>
            )}
          </button>

          {error && (
            <div className="mt-6 p-4 bg-red-50 text-red-600 rounded-2xl text-[11px] font-bold flex items-center gap-2">
              <AlertTriangle className="w-4 h-4 flex-shrink-0" />
              <p>{error}</p>
            </div>
          )}

          <div className="mt-12 flex flex-col gap-4">
             <div className="flex items-center gap-2 justify-center text-[10px] text-slate-400 font-bold uppercase tracking-widest">
                <ShieldCheck className="w-3.5 h-3.5" />
                Login seguro via Google
             </div>
             <div className="border-t border-slate-100 pt-5">
               <a 
                 href="https://ai.google.dev/gemini-api/docs/billing" 
                 target="_blank" 
                 rel="noopener noreferrer"
                 className="text-[10px] text-slate-400 font-bold hover:text-indigo-600 transition-colors uppercase tracking-widest flex items-center justify-center gap-1.5"
               >
                 Info de Cotas e Uso
                 <ExternalLink className="w-3 h-3" />
               </a>
             </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900 flex flex-col">
      <header className="bg-white border-b border-slate-100 sticky top-0 z-40">
        <div className="max-w-7xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-indigo-600 p-2 rounded-xl">
              <BrainCircuit className="text-white w-5 h-5" />
            </div>
            <h1 className="text-lg font-black tracking-tighter text-slate-900">Creative Analyzer</h1>
          </div>

          <div className="flex items-center gap-4">
            <button 
