        } else {
          // Tenta novamente em 500ms se não encontrar o serviço
          setTimeout(check, 500);
        }
      };
      check();
    };
    checkAuth();
  }, []);

  const handleGoogleLogin = async () => {
    setError(null);
    setIsLoggingIn(true);
    try {
      // @ts-ignore
      if (typeof window.aistudio !== 'undefined') {
        // @ts-ignore
        await window.aistudio.openSelectKey();
        // Conforme diretriz de race condition: assumir sucesso imediato
        setIsAuthenticated(true);
      } else {
        throw new Error("O serviço de autenticação Google ainda não está pronto. Tente novamente em alguns segundos.");
      }
    } catch (err: any) {
      console.error("Login failed:", err);
      setError(err?.message || "Erro ao abrir o login do Google. Verifique se pop-ups estão permitidos.");
      setIsAuthenticated(false);
    } finally {
      setIsLoggingIn(false);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (!file.type.startsWith('image/')) {
        setError("Por favor, selecione uma imagem.");
        return;
      }
      setMimeType(file.type);
      const reader = new FileReader();
      reader.onloadend = () => {
        setImage(reader.result as string);
        setError(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAnalyze = async () => {
    if (!image && !copyText) {
      setError("Insira o texto ou uma imagem para análise.");
      return;
    }

    setStatus(AnalysisStatus.LOADING);
    setError(null);
    setResult(null);

    try {
      const data = await analyzeCreative(image, mimeType, copyText, context);
      setResult(data);
      setStatus(AnalysisStatus.SUCCESS);
    } catch (err: any) {
      if (err.message?.includes("Requested entity was not found")) {
        setError("Sua sessão do Google expirou. Por favor, faça login novamente.");
        setIsAuthenticated(false);
      } else {
        setError("Erro na análise. Verifique sua conta Google ou limites de uso.");
      }
      setStatus(AnalysisStatus.ERROR);
    }
  };

  const handleGetSuggestions = async () => {
    if (!result || !copyText) return;
    setIsSuggesting(true);
    try {
      const { suggestions, sources } = await suggestNewCopys(result, copyText, context, selectedBrand);
      setResult({ ...result, suggestedCopys: suggestions, sources: sources });
    } catch (err: any) {
      if (err.message?.includes("Requested entity was not found")) {
        setIsAuthenticated(false);
      }
    } finally {
      setIsSuggesting(false);
    }
  };

  const clearImage = () => {
    setImage(null);
    setMimeType('');
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  if (isAuthenticated === null) {
    return (
      <div className="min-h-screen bg-white flex items-center justify-center">
        <div className="flex flex-col items-center gap-4">
          <Loader2 className="w-10 h-10 text-indigo-600 animate-spin" />
          <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Iniciando serviço Google...</p>
        </div>
      </div>
    );
  }

  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-6 relative overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-1.5 bg-gradient-to-r from-blue-500 via-red-500 to-yellow-500" />

        <div className="max-w-md w-full bg-white rounded-[3rem] shadow-2xl border border-slate-100 p-12 text-center relative z-10 animate-in fade-in zoom-in-95 duration-500">
