          >
            {isLoggingIn ? (
              <Loader2 className="w-5 h-5 animate-spin" />
            ) : (
              <>
                <div className="w-6 h-6 flex items-center justify-center bg-white rounded-full p-1">
                  <svg viewBox="0 0 24 24" className="w-4 h-4">
                    <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z" fill="#4285F4"/><path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853"/><path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l3.66-2.84z" fill="#FBBC05"/><path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335"/>
                  </svg>
                </div>
                <span className="font-black text-xs uppercase tracking-widest">Entrar com Google</span>
              </>
            )}
          </button>

          {error && (
            <div className="mt-6 p-4 bg-red-50 text-red-600 border border-red-100 rounded-2xl text-[11px] font-bold flex items-start gap-2 text-left animate-in slide-in-from-top-2">
              <AlertTriangle className="w-4 h-4 flex-shrink-0 mt-0.5" />
              <p>{error}</p>
            </div>
          )}

          <div className="mt-12 flex flex-col gap-4">
             <div className="flex items-center gap-2 justify-center text-[10px] text-slate-400 font-bold uppercase tracking-widest">
                <ShieldCheck className="w-3.5 h-3.5" />
                Sua conta está segura e protegida
             </div>
             <div className="border-t border-slate-100 pt-5">
               <a 
                 href="https://ai.google.dev/gemini-api/docs/billing" 
                 target="_blank" 
                 rel="noopener noreferrer"
                 className="text-[10px] text-slate-400 font-bold hover:text-indigo-600 transition-colors uppercase tracking-[0.2em] flex items-center justify-center gap-1.5"
               >
                 Acesse sua conta Google AI
                 <ExternalLink className="w-3 h-3" />
               </a>
             </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900 flex flex-col">
      <header className="bg-white border-b border-slate-100 sticky top-0 z-40">
