                  <div className="relative w-full rounded-[1.5rem] overflow-hidden border border-slate-100 bg-slate-50">
                    <img src={image} alt="Preview" className="w-full h-auto object-contain max-h-60 mx-auto" />
                    <button onClick={clearImage} className="absolute top-4 right-4 p-2 bg-white/90 backdrop-blur-sm text-red-500 rounded-full shadow-lg border border-slate-100 hover:bg-red-50 transition-all">
                      <X className="w-4 h-4" />
                    </button>
                  </div>
                )}
              </div>

              <div className="pt-6 border-t border-slate-50 space-y-4">
                <div className="mb-4">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 block">Contexto</label>
                  <input
                    type="text"
                    className="w-full bg-slate-50 border border-slate-100 rounded-xl p-4 text-xs font-bold outline-none focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 transition-all"
                    placeholder="Ex: Instagram, LinkedIn..."
                    value={context}
                    onChange={(e) => setContext(e.target.value)}
                  />
                </div>

                {error && (
                  <div className="p-4 bg-red-50 border border-red-100 rounded-2xl flex items-start gap-3 text-red-600 text-[11px] font-bold">
                    <AlertTriangle className="w-4 h-4 flex-shrink-0" />
                    <p>{error}</p>
                  </div>
                )}

                <button
                  onClick={handleAnalyze}
                  disabled={status === AnalysisStatus.LOADING || (!image && !copyText)}
                  className={`w-full py-5 rounded-[1.5rem] font-black text-xs uppercase tracking-[0.2em] flex items-center justify-center gap-3 transition-all active:scale-95 shadow-xl ${
                    status === AnalysisStatus.LOADING || (!image && !copyText)
                    ? 'bg-slate-100 text-slate-400 cursor-not-allowed shadow-none' 
                    : 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-indigo-100'
                  }`}
                >
                  {status === AnalysisStatus.LOADING ? (
                    <><Loader2 className="w-5 h-5 animate-spin" /> Analisando...</>
                  ) : (
                    <><Sparkles className="w-5 h-5" /> Analisar Criativo</>
                  )}
                </button>

                {status === AnalysisStatus.SUCCESS && result && !result.suggestedCopys && (
                  <button
                    onClick={handleGetSuggestions}
                    disabled={isSuggesting}
                    className="w-full py-4 rounded-[1.5rem] border-2 border-indigo-600 text-indigo-600 font-black text-xs uppercase tracking-[0.2em] flex items-center justify-center gap-3 hover:bg-indigo-50 transition-all active:scale-95"
                  >
                    {isSuggesting ? (
                      <><Loader2 className="w-4 h-4 animate-spin" /> Otimizando...</>
                    ) : (
                      <><Wand2 className="w-4 h-4" /> Sugerir Melhorias</>
                    )}
                  </button>
                )}
              </div>
            </div>
          </div>

          <div className="xl:col-span-7">
            {status === AnalysisStatus.IDLE && (
              <div className="h-full min-h-[500px] flex flex-col items-center justify-center text-center p-12 bg-white/50 rounded-[3rem] border-2 border-dashed border-slate-200">
                <div className="bg-white p-8 rounded-[2rem] shadow-sm mb-6">
                  <BrainCircuit className="w-16 h-16 text-slate-100" />
                </div>
                <h3 className="text-xl font-bold text-slate-400">Aguardando conteúdo</h3>
                <p className="text-slate-400 max-w-sm mt-3 text-sm leading-relaxed">Insira sua peça no painel ao lado para identificar gatilhos e performance.</p>
              </div>
            )}

            {status === AnalysisStatus.LOADING && (
              <div className="h-full flex flex-col items-center justify-center text-center p-12">
                <div className="relative mb-10">
                  <div className="w-24 h-24 border-8 border-slate-50 border-t-indigo-600 rounded-full animate-spin"></div>
                  <div className="absolute inset-0 flex items-center justify-center">
                    <Sparkles className="w-8 h-8 text-indigo-600 animate-pulse" />
                  </div>
                </div>
                <h3 className="text-2xl font-black text-slate-800 tracking-tight">Analisando</h3>
                <p className="text-slate-500 text-sm mt-3 font-medium">Seu Gemini está decodificando o criativo...</p>
              </div>
            )}

            {status === AnalysisStatus.SUCCESS && result && (
              <ResultDisplay data={result} />
            )}
          </div>
        </div>
      </main>

      <footer className="py-10 border-t border-slate-100 text-center">
        <p className="text-[10px] font-black text-slate-300 uppercase tracking-[0.4em]">Creative Analyzer • Powered by Google Gemini</p>
      </footer>

      <TriggersModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} />
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { analyzeCreative, suggestNewCopys } from './services/geminiService';
import { AnalysisResult, AnalysisStatus, Brand, BRANDS } from './types';
import ResultDisplay from './components/ResultDisplay';
import TriggersModal from './components/TriggersModal';
import { 
  Sparkles, 
  AlertTriangle, 
  Loader2, 
  BrainCircuit, 
  Upload, 
  X, 
  Wand2, 
  BookOpen, 
  ChevronDown, 
  Check, 
  Globe, 
  User, 
  ShieldCheck, 
  ExternalLink
} from 'lucide-react';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean | null>(null);
  const [image, setImage] = useState<string | null>(null);
  const [mimeType, setMimeType] = useState<string>('');
  const [copyText, setCopyText] = useState('');
  const [context, setContext] = useState('');
  const [status, setStatus] = useState<AnalysisStatus>(AnalysisStatus.IDLE);
  const [result, setResult] = useState<AnalysisResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isSuggesting, setIsSuggesting] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isBrandMenuOpen, setIsBrandMenuOpen] = useState(false);
  const [selectedBrand, setSelectedBrand] = useState<Brand>('Anhanguera');
  const [isLoggingIn, setIsLoggingIn] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const brandMenuRef = useRef<HTMLDivElement>(null);

  // Inicialização robusta
  useEffect(() => {
    const initAuth = async () => {
      // Tenta verificar a chave. Se após 1.5s não houver resposta, assume que precisa logar.
      const timeoutPromise = new Promise((resolve) => setTimeout(() => resolve('timeout'), 1500));

      const checkPromise = (async () => {
        // @ts-ignore
        if (window.aistudio) {
          try {
            // @ts-ignore
            return await window.aistudio.hasSelectedApiKey();
          } catch (e) {
            return false;
          }
        }
        return null;
      })();

      const result = await Promise.race([checkPromise, timeoutPromise]);

      if (result === 'timeout' || result === null || result === false) {
        setIsAuthenticated(false);
      } else {
        setIsAuthenticated(true);
      }
    };

    initAuth();
  }, []);

  const handleGoogleLogin = async () => {
    setError(null);
    setIsLoggingIn(true);
    try {
      // @ts-ignore
      if (typeof window.aistudio !== 'undefined') {
        // @ts-ignore
        await window.aistudio.openSelectKey();
        // IMPORTANTE: Conforme diretriz, assumimos sucesso imediato para evitar race condition
        setIsAuthenticated(true);
      } else {
        throw new Error("O serviço de autenticação Google não foi detectado. Tente recarregar a página.");
      }
    } catch (err: any) {
      console.error("Login failed:", err);
      setError("Não foi possível abrir o login. Verifique se o navegador bloqueou o pop-up.");
      setIsAuthenticated(false);
    } finally {
      setIsLoggingIn(false);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (!file.type.startsWith('image/')) {
        setError("Por favor, selecione uma imagem.");
        return;
      }
      setMimeType(file.type);
      const reader = new FileReader();
      reader.onloadend = () => {
        setImage(reader.result as string);
        setError(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAnalyze = async () => {
    if (!image && !copyText) {
      setError("Insira o texto ou uma imagem para análise.");
      return;
    }

    setStatus(AnalysisStatus.LOADING);
    setError(null);
    setResult(null);

    try {
      const data = await analyzeCreative(image, mimeType, copyText, context);
      setResult(data);
      setStatus(AnalysisStatus.SUCCESS);
    } catch (err: any) {
      if (err.message?.includes("Requested entity was not found")) {
        setError("Sua sessão do Google expirou ou a chave é inválida. Clique no ícone de usuário para relogar.");
        // Não desloga automaticamente para não frustrar o usuário, mas avisa
      } else {
        setError("Erro na análise. Verifique sua conexão ou tente novamente.");
      }
      setStatus(AnalysisStatus.ERROR);
    }
  };

  const handleGetSuggestions = async () => {
    if (!result || !copyText) return;
    setIsSuggesting(true);
    try {
      const { suggestions, sources } = await suggestNewCopys(result, copyText, context, selectedBrand);
      setResult({ ...result, suggestedCopys: suggestions, sources: sources });
    } catch (err: any) {
      // Silencioso ou log
    } finally {
      setIsSuggesting(false);
    }
  };

  const clearImage = () => {
    setImage(null);
    setMimeType('');
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  // ESTADO DE CARREGAMENTO INICIAL
  if (isAuthenticated === null) {
    return (
      <div className="min-h-screen bg-white flex flex-col items-center justify-center p-10 text-center">
        <div className="relative mb-8">
          <div className="w-16 h-16 border-4 border-slate-100 border-t-indigo-600 rounded-full animate-spin"></div>
          <div className="absolute inset-0 flex items-center justify-center">
            <BrainCircuit className="w-6 h-6 text-indigo-600" />
          </div>
        </div>
        <h2 className="text-sm font-black text-slate-800 uppercase tracking-[0.3em]">Carregando Inteligência</h2>
        <p className="text-xs font-bold text-slate-400 mt-2 uppercase tracking-widest">Sincronizando com Google...</p>
      </div>
    );
  }

  // TELA DE LOGIN (FOCO TOTAL EM E-MAIL/GOOGLE)
  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-6 relative overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-1.5 bg-gradient-to-r from-blue-500 via-red-500 to-yellow-500" />

        <div className="max-w-md w-full bg-white rounded-[3rem] shadow-2xl border border-slate-100 p-12 text-center relative z-10 animate-in fade-in zoom-in-95 duration-500">
          <div className="w-20 h-20 bg-indigo-600 rounded-[2rem] flex items-center justify-center mx-auto mb-10 shadow-xl shadow-indigo-100 transform rotate-3">
            <BrainCircuit className="text-white w-10 h-10" />
          </div>

          <h1 className="text-3xl font-black text-slate-900 mb-4 tracking-tighter">Creative Analyzer</h1>
          <p className="text-slate-500 font-medium mb-12 leading-relaxed text-sm px-4">
            Acesse a ferramenta utilizando sua conta Google para analisar a performance de seus anúncios com IA.
          </p>

          <button 
            onClick={handleGoogleLogin}
            disabled={isLoggingIn}
            className="w-full bg-slate-900 text-white py-4.5 rounded-[1.5rem] flex items-center justify-center gap-4 hover:bg-indigo-600 transition-all group active:scale-[0.98] shadow-xl shadow-slate-200 disabled:opacity-50"
          >
            {isLoggingIn ? (
              <Loader2 className="w-5 h-5 animate-spin" />
            ) : (
              <>
                <div className="w-6 h-6 flex items-center justify-center bg-white rounded-full p-1">
                  <svg viewBox="0 0 24 24" className="w-4 h-4">
                    <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z" fill="#4285F4"/><path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853"/><path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l3.66-2.84z" fill="#FBBC05"/><path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335"/>
                  </svg>
                </div>
                <span className="font-black text-xs uppercase tracking-widest">Entrar com Google</span>
              </>
            )}
          </button>

          {error && (
            <div className="mt-6 p-4 bg-red-50 text-red-600 border border-red-100 rounded-2xl text-[11px] font-bold flex items-start gap-2 text-left animate-in slide-in-from-top-2">
              <AlertTriangle className="w-4 h-4 flex-shrink-0 mt-0.5" />
              <p>{error}</p>
            </div>
          )}

          <div className="mt-12 flex flex-col gap-4">
             <div className="flex items-center gap-2 justify-center text-[10px] text-slate-400 font-bold uppercase tracking-widest">
                <ShieldCheck className="w-3.5 h-3.5" />
