             </div>
             <div className="border-t border-slate-100 pt-5">
               <a 
                 href="https://ai.google.dev/gemini-api/docs/billing" 
                 target="_blank" 
                 rel="noopener noreferrer"
                 className="text-[10px] text-slate-400 font-bold hover:text-indigo-600 transition-colors uppercase tracking-[0.2em] flex items-center justify-center gap-1.5"
               >
                 Sobre limites de uso da conta
                 <ExternalLink className="w-3 h-3" />
               </a>
             </div>
          </div>
        </div>
      </div>
    );
  }

  // INTERFACE PRINCIPAL
  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900 flex flex-col">
      <header className="bg-white border-b border-slate-100 sticky top-0 z-40">
        <div className="max-w-7xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-indigo-600 p-2 rounded-xl">
              <BrainCircuit className="text-white w-5 h-5" />
            </div>
            <h1 className="text-lg font-black tracking-tighter text-slate-900">Creative Analyzer</h1>
          </div>

          <div className="flex items-center gap-4">
            <button 
              onClick={() => setIsModalOpen(true)}
              className="flex items-center gap-2 px-3 py-2 text-slate-600 hover:bg-slate-50 rounded-xl transition-all font-bold text-xs uppercase tracking-widest"
            >
              <BookOpen className="w-4 h-4 text-indigo-600" />
              <span className="hidden md:inline">Gatilhos</span>
            </button>

            <div className="relative" ref={brandMenuRef}>
              <button 
                onClick={() => setIsBrandMenuOpen(!isBrandMenuOpen)}
                className={`flex items-center gap-2 px-4 py-2 rounded-xl transition-all font-bold text-[10px] uppercase border tracking-widest ${
                  isBrandMenuOpen ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-slate-50 text-slate-600 border-slate-100 hover:bg-slate-100'
                }`}
              >
                <Globe className="w-3.5 h-3.5" />
                <span>{selectedBrand}</span>
                <ChevronDown className={`w-3.5 h-3.5 transition-transform ${isBrandMenuOpen ? 'rotate-180' : ''}`} />
              </button>

              {isBrandMenuOpen && (
                <div className="absolute right-0 mt-3 w-56 bg-white border border-slate-100 rounded-[1.5rem] shadow-2xl py-3 z-50 animate-in fade-in slide-in-from-top-2">
                  <div className="px-5 py-2 border-b border-slate-50 mb-2">
                    <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Tom de Voz</p>
                  </div>
                  {BRANDS.map(brand => (
                    <button
                      key={brand}
                      onClick={() => { setSelectedBrand(brand); setIsBrandMenuOpen(false); }}
                      className={`w-full px-5 py-2.5 text-left text-[11px] font-bold flex items-center justify-between hover:bg-slate-50 ${
                        selectedBrand === brand ? 'text-indigo-600 bg-indigo-50/50' : 'text-slate-600'
                      }`}
                    >
                      {brand}
                      {selectedBrand === brand && <Check className="w-4 h-4" />}
                    </button>
                  ))}
                </div>
              )}
            </div>

            <button 
              onClick={handleGoogleLogin}
              className="w-10 h-10 bg-slate-50 rounded-full flex items-center justify-center border border-slate-200 hover:border-indigo-400 hover:bg-white transition-all group"
              title="Trocar de Conta Google"
            >
              <User className="w-5 h-5 text-slate-400 group-hover:text-indigo-600" />
            </button>
          </div>
        </div>
      </header>

      <main className="flex-grow max-w-7xl mx-auto w-full px-6 py-10">
        <div className="grid grid-cols-1 xl:grid-cols-12 gap-10">

          <div className="xl:col-span-5 space-y-6">
            <div className="bg-white rounded-[2.5rem] p-8 shadow-sm border border-slate-100">
              <div className="mb-6">
