                        className={`w-full px-4 py-2.5 text-left text-[11px] font-bold flex items-center justify-between rounded-xl transition-colors ${
                          selectedBrand === brand ? 'text-indigo-600 bg-indigo-50' : 'text-slate-600 hover:bg-slate-50'
