        </div>
      </main>

      <footer className="py-10 border-t border-slate-100 text-center">
        <p className="text-[8px] font-black text-slate-300 uppercase tracking-[0.4em]">Creative Analyzer • Powered by Gemini Flash 3.0</p>
      </footer>

      <TriggersModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} />
    </div>
  );
};

