const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean | null>(null);
  const [image, setImage] = useState<string | null>(null);
  const [mimeType, setMimeType] = useState<string>('');
  const [copyText, setCopyText] = useState('');
  const [platform, setPlatform] = useState<Platform>('Meta');
  const [status, setStatus] = useState<AnalysisStatus>(AnalysisStatus.IDLE);
  const [result, setResult] = useState<AnalysisResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isSuggesting, setIsSuggesting] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isBrandMenuOpen, setIsBrandMenuOpen] = useState(false);
  const [selectedBrand, setSelectedBrand] = useState<Brand>('Anhanguera');
  const [isLoggingIn, setIsLoggingIn] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const brandMenuRef = useRef<HTMLDivElement>(null);

  // Monitoramento de cliques fora do menu de marcas
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (brandMenuRef.current && !brandMenuRef.current.contains(event.target as Node)) {
        setIsBrandMenuOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Inicialização resiliente do serviço de autenticação
  useEffect(() => {
    let attempts = 0;
    const maxAttempts = 10;

    const checkAvailability = async () => {
      // @ts-ignore
      if (window.aistudio) {
        try {
          // @ts-ignore
          const hasKey = await window.aistudio.hasSelectedApiKey();
          setIsAuthenticated(hasKey);
        } catch (e) {
          setIsAuthenticated(false);
        }
        return;
      }

      attempts++;
      if (attempts < maxAttempts) {
        setTimeout(checkAvailability, 500);
      } else {
        setIsAuthenticated(false);
      }
    };

    checkAvailability();
  }, []);

  const handleGoogleLogin = async () => {
    setError(null);
    setIsLoggingIn(true);
    try {
      // @ts-ignore
      if (window.aistudio && typeof window.aistudio.openSelectKey === 'function') {
        // @ts-ignore
        await window.aistudio.openSelectKey();
        setIsAuthenticated(true);
      } else {
        if (process.env.API_KEY) {
          setIsAuthenticated(true);
        } else {
          throw new Error("Serviço de autenticação não disponível.");
        }
      }
    } catch (err: any) {
      console.error("Erro de login:", err);
      setError("Não foi possível conectar. Verifique os pop-ups.");
      setIsAuthenticated(false);
    } finally {
      setIsLoggingIn(false);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (!file.type.startsWith('image/')) {
        setError("Por favor, selecione uma imagem.");
        return;
      }
      setMimeType(file.type);
      const reader = new FileReader();
      reader.onloadend = () => {
        setImage(reader.result as string);
        setError(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAnalyze = async () => {
    if (!image && !copyText) {
      setError("Insira o texto ou uma imagem para análise.");
      return;
    }

    setStatus(AnalysisStatus.LOADING);
    setError(null);
    setResult(null);

    try {
      const data = await analyzeCreative(image, mimeType, copyText, platform);
      setResult(data);
      setStatus(AnalysisStatus.SUCCESS);
    } catch (err: any) {
      console.error("Erro na análise:", err);
      if (err.message?.includes("Requested entity was not found")) {
        setError("Sua sessão do Google expirou.");
        setIsAuthenticated(false);
      } else {
        setError("Erro ao processar. Tente novamente.");
      }
      setStatus(AnalysisStatus.ERROR);
    }
  };

  const handleGetSuggestions = async () => {
    if (!result || !copyText) return;
    setIsSuggesting(true);
    try {
      const { suggestions, sources } = await suggestNewCopys(result, copyText, platform, selectedBrand);
      setResult({ ...result, suggestedCopys: suggestions, sources: sources });
    } catch (err: any) {
      if (err.message?.includes("Requested entity was not found")) {
        setIsAuthenticated(false);
      }
    } finally {
      setIsSuggesting(false);
    }
  };

  const clearImage = () => {
    setImage(null);
    setMimeType('');
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const getPlatformIcon = (p: Platform) => {
    switch (p) {
      case 'Meta': return <Facebook className="w-3.5 h-3.5" />;
      case 'Google': return <Search className="w-3.5 h-3.5" />;
      case 'TikTok': return <Smartphone className="w-3.5 h-3.5" />;
      case 'SITES/CRM': return <Layout className="w-3.5 h-3.5" />;
      default: return <Layout className="w-3.5 h-3.5" />;
    }
  };

  if (isAuthenticated === null) {
    return (
      <div className="min-h-screen bg-white flex flex-col items-center justify-center p-12 text-center">
        <div className="relative mb-8">
          <div className="w-16 h-16 border-4 border-slate-100 border-t-indigo-600 rounded-full animate-spin"></div>
          <div className="absolute inset-0 flex items-center justify-center">
            <BrainCircuit className="w-6 h-6 text-indigo-600" />
          </div>
        </div>
        <h2 className="text-sm font-black text-slate-900 uppercase tracking-[0.4em] mb-2">Creative AI</h2>
        <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest animate-pulse">
          Validando conexão com Google...
        </p>
      </div>
    );
  }

  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-[#fcfdff] flex items-center justify-center p-6 relative overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-1.5 bg-gradient-to-r from-blue-500 via-red-500 to-yellow-500" />
        <div className="max-w-md w-full bg-white rounded-[3rem] shadow-2xl border border-slate-100 p-12 text-center relative z-10 animate-in fade-in zoom-in-95 duration-500">
          <div className="w-20 h-20 bg-indigo-600 rounded-[2rem] flex items-center justify-center mx-auto mb-10 shadow-xl shadow-indigo-100 transform rotate-3">
            <BrainCircuit className="text-white w-10 h-10" />
          </div>
          <h1 className="text-3xl font-black text-slate-900 mb-4 tracking-tighter">Creative Analyzer</h1>
          <p className="text-slate-500 font-medium mb-12 leading-relaxed text-sm px-4">
            Utilize sua conta Google para analisar gatilhos mentais e atributos em suas peças.
          </p>
          <button 
            onClick={handleGoogleLogin}
            disabled={isLoggingIn}
            className="w-full bg-slate-900 text-white py-5 rounded-[1.5rem] flex items-center justify-center gap-4 hover:bg-indigo-600 transition-all group active:scale-[0.98] shadow-2xl shadow-slate-200 disabled:opacity-50"
          >
            {isLoggingIn ? <Loader2 className="w-5 h-5 animate-spin" /> : <><div className="bg-white p-1 rounded-full"><svg viewBox="0 0 24 24" className="w-5 h-5"><path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z" fill="#4285F4"/><path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853"/><path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l3.66-2.84z" fill="#FBBC05"/><path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335"/></svg></div><span className="font-black text-xs uppercase tracking-[0.2em]">Conectar via Google</span></>}
          </button>
          {error && <div className="mt-8 p-5 bg-red-50 border border-red-100 text-red-600 rounded-3xl text-[11px] font-bold flex items-start gap-3 text-left animate-in slide-in-from-top-2"><AlertTriangle className="w-5 h-5 flex-shrink-0 mt-0.5" /><p className="leading-relaxed">{error}</p></div>}
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900 flex flex-col">
      <header className="bg-white/80 backdrop-blur-md border-b border-slate-100 sticky top-0 z-40">
        <div className="max-w-7xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-indigo-600 p-2 rounded-xl shadow-lg shadow-indigo-100">
              <BrainCircuit className="text-white w-5 h-5" />
            </div>
            <h1 className="text-lg font-black tracking-tighter text-slate-900">Creative Analyzer</h1>
          </div>
          <div className="flex items-center gap-4">
            <button onClick={() => setIsModalOpen(true)} className="flex items-center gap-2 px-4 py-2 text-slate-600 hover:bg-slate-50 rounded-xl transition-all font-bold text-xs uppercase tracking-widest">
              <BookOpen className="w-4 h-4 text-indigo-600" />
              <span className="hidden md:inline">Gatilhos</span>
            </button>
            <div className="relative" ref={brandMenuRef}>
              <button onClick={() => setIsBrandMenuOpen(!isBrandMenuOpen)} className={`flex items-center gap-3 px-4 py-2.5 rounded-xl transition-all font-bold text-[10px] uppercase border tracking-[0.2em] ${isBrandMenuOpen ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-slate-50 text-slate-600 border-slate-100 hover:bg-slate-100'}`}>
                <Globe className="w-3.5 h-3.5" />
                <span>{selectedBrand}</span>
                <ChevronDown className={`w-3.5 h-3.5 transition-transform duration-300 ${isBrandMenuOpen ? 'rotate-180' : ''}`} />
              </button>
              {isBrandMenuOpen && (
                <div className="absolute right-0 mt-3 w-64 bg-white border border-slate-100 rounded-[2rem] shadow-2xl py-4 z-50 animate-in fade-in slide-in-from-top-2">
                  <div className="px-6 py-2 border-b border-slate-50 mb-3"><p className="text-[9px] font-black text-slate-300 uppercase tracking-[0.3em]">Diretriz de Marca</p></div>
                  <div className="max-h-64 overflow-y-auto px-2 space-y-1 custom-scrollbar">
                    {BRANDS.map(brand => (
                      <button key={brand} onClick={() => { setSelectedBrand(brand); setIsBrandMenuOpen(false); }} className={`w-full px-4 py-2.5 text-left text-[11px] font-bold flex items-center justify-between rounded-xl transition-colors ${selectedBrand === brand ? 'text-indigo-600 bg-indigo-50' : 'text-slate-600 hover:bg-slate-50'}`}>
                        {brand}{selectedBrand === brand && <Check className="w-4 h-4" />}
                      </button>
                    ))}
                  </div>
                </div>
              )}
            </div>
            <button onClick={handleGoogleLogin} className="w-10 h-10 bg-slate-50 rounded-full flex items-center justify-center border border-slate-200 hover:border-indigo-400 hover:bg-white transition-all group relative">
              <User className="w-5 h-5 text-slate-400 group-hover:text-indigo-600" />
              <div className="absolute -bottom-1 -right-1 w-3 h-3 bg-emerald-500 rounded-full border-2 border-white" />
            </button>
          </div>
        </div>
      </header>

      <main className="flex-grow max-w-7xl mx-auto w-full px-6 py-10">
        <div className="grid grid-cols-1 xl:grid-cols-12 gap-10">
          <div className="xl:col-span-5 space-y-6">
            <div className="bg-white rounded-[2.5rem] p-8 shadow-sm border border-slate-100 sticky top-24">
              <div className="mb-6">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 block">Texto da Copy</label>
                <textarea className="w-full bg-slate-50 border border-slate-100 rounded-[1.5rem] p-5 text-slate-800 focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 outline-none transition-all min-h-[140px] text-sm leading-relaxed" placeholder="Cole aqui o texto publicitário..." value={copyText} onChange={(e) => setCopyText(e.target.value)} />
              </div>

              <div className="mb-8">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 block">Imagem do Criativo</label>
                <input type="file" ref={fileInputRef} onChange={handleFileChange} accept="image/*" className="hidden" />
                {!image ? (
                  <div onClick={() => fileInputRef.current?.click()} className="w-full h-44 border-2 border-dashed border-slate-100 rounded-[1.5rem] flex flex-col items-center justify-center gap-3 cursor-pointer hover:border-indigo-400 hover:bg-indigo-50/20 transition-all group">
                    <Upload className="w-6 h-6 text-slate-300 group-hover:text-indigo-600" /><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Upload de Mídia</p>
                  </div>
                ) : (
                  <div className="relative w-full rounded-[1.5rem] overflow-hidden border border-slate-100 bg-slate-50 group">
                    <img src={image} alt="Preview" className="w-full h-auto object-contain max-h-60 mx-auto" />
                    <button onClick={clearImage} className="absolute top-4 right-4 p-2.5 bg-white/90 backdrop-blur-sm text-red-500 rounded-full shadow-lg border border-slate-100 hover:bg-red-50 transition-all active:scale-90"><X className="w-4 h-4" /></button>
                  </div>
                )}
              </div>

              <div className="pt-6 border-t border-slate-50 space-y-4">
                <div className="mb-4">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 block">Plataforma de Mídia</label>
                  <div className="grid grid-cols-2 gap-2">
                    {PLATFORMS.map((p) => (
                      <button
                        key={p}
                        onClick={() => setPlatform(p)}
                        className={`flex items-center gap-3 px-4 py-3 rounded-xl border font-bold text-[11px] uppercase tracking-wider transition-all ${
                          platform === p 
                          ? 'bg-indigo-600 text-white border-indigo-600 shadow-md' 
                          : 'bg-slate-50 text-slate-500 border-slate-100 hover:bg-slate-100'
                        }`}
                      >
                        {getPlatformIcon(p)}
                        {p}
                      </button>
                    ))}
                  </div>
                </div>

                {error && <div className="p-4 bg-red-50 border border-red-100 rounded-2xl flex items-start gap-3 text-red-600 text-[11px] font-bold animate-in slide-in-from-top-2"><AlertTriangle className="w-4 h-4 flex-shrink-0" /><p>{error}</p></div>}

                <button onClick={handleAnalyze} disabled={status === AnalysisStatus.LOADING || (!image && !copyText)} className={`w-full py-5 rounded-[1.5rem] font-black text-xs uppercase tracking-[0.2em] flex items-center justify-center gap-3 transition-all active:scale-95 shadow-xl ${status === AnalysisStatus.LOADING || (!image && !copyText) ? 'bg-slate-100 text-slate-400 cursor-not-allowed shadow-none' : 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-indigo-100'}`}>
                  {status === AnalysisStatus.LOADING ? <><Loader2 className="w-5 h-5 animate-spin" /> Processando...</> : <><Sparkles className="w-5 h-5" /> Analisar para {platform}</>}
                </button>

                {status === AnalysisStatus.SUCCESS && result && !result.suggestedCopys && (
                  <button onClick={handleGetSuggestions} disabled={isSuggesting} className="w-full py-4 rounded-[1.5rem] border-2 border-indigo-600 text-indigo-600 font-black text-xs uppercase tracking-[0.2em] flex items-center justify-center gap-3 hover:bg-indigo-50 transition-all active:scale-95">
                    {isSuggesting ? <><Loader2 className="w-4 h-4 animate-spin" /> Redigindo...</> : <><Wand2 className="w-4 h-4" /> Sugerir Melhorias para {platform}</>}
                  </button>
                )}
              </div>
            </div>
          </div>

          <div className="xl:col-span-7">
            {status === AnalysisStatus.IDLE && (
              <div className="h-full min-h-[500px] flex flex-col items-center justify-center text-center p-12 bg-white/50 rounded-[3rem] border-2 border-dashed border-slate-200">
                <div className="bg-white p-8 rounded-[2.5rem] shadow-sm mb-8 border border-slate-50"><BrainCircuit className="w-16 h-16 text-slate-100" /></div>
                <h3 className="text-xl font-bold text-slate-400 uppercase tracking-[0.3em]">Módulo de Inteligência</h3>
                <p className="text-slate-400 max-w-sm mt-4 text-xs leading-relaxed font-bold uppercase tracking-widest">Selecione a plataforma e insira o conteúdo para um diagnóstico otimizado.</p>
              </div>
            )}
            {status === AnalysisStatus.LOADING && (
              <div className="h-full flex flex-col items-center justify-center text-center p-12 animate-in fade-in duration-500">
                <div className="relative mb-10"><div className="w-24 h-24 border-8 border-slate-50 border-t-indigo-600 rounded-full animate-spin"></div><div className="absolute inset-0 flex items-center justify-center"><Sparkles className="w-8 h-8 text-indigo-600 animate-pulse" /></div></div>
                <h3 className="text-2xl font-black text-slate-800 tracking-tight">Decodificando Criativo</h3>
                <p className="text-slate-500 text-sm mt-3 font-medium uppercase tracking-widest">Analisando especificidades para {platform}...</p>
              </div>
            )}
            {status === AnalysisStatus.SUCCESS && result && <ResultDisplay data={result} />}
          </div>
        </div>
      </main>
      <footer className="py-10 border-t border-slate-100 text-center"><p className="text-[8px] font-black text-slate-300 uppercase tracking-[0.4em]">Creative Analyzer • Powered by Gemini Flash 3.0</p></footer>
      <TriggersModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} />
    </div>
  );
};

