export const BRANDS: Brand[] = [
  'Anhanguera',
  'Unopar',
  'Unime',
  'Pitágoras',
  'Unic',
  'Uniderp',
  'Anglo',
  'Singularidades',
  'Red Balloon'
];

export type Platform = 'Meta' | 'Google' | 'TikTok' | 'SITES/CRM';

export const PLATFORMS: Platform[] = ['Meta', 'Google', 'TikTok', 'SITES/CRM'];

import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";
import { AnalysisResult, SuggestedCopy, GroundingSource, Brand, Platform } from "../types";

const KNOWLEDGE_BASE_PROMPT = `
Você é um especialista em análise de peças publicitárias e redação (copywriting). 
Sua análise deve ser baseada ESTRITAMENTE na seguinte taxonomia da planilha oficial:

CATEGORIA: Atributo
- Prova Social: Muitas pessoas já fizeram e deu certo.
- Autoridade: Validação por instituições, especialistas ou dados oficiais.
- Resultados Concretos: Métricas claras: emprego, salário, aprovação, crescimento.
- Casos Reais: Histórias objetivas de pessoas semelhantes ao público.
- Eficiência: Menos tempo, menos esforço, mais resultado.
- Credibilidade: Tradição, reputação e histórico confiável.
- Segurança: Estabilidade, regulamentação, estrutura sólida.
- Qualidade Percebida: Sensação de algo bem feito e profissional.
- Pertencimento: Fazer parte de algo maior ou reconhecido.
- Identificação: Linguagem, estética e valores próximos do público.
- Confiabilidade: Cumpre o que promete, sem surpresas.
- Clareza: Comunicação simples, objetiva e transparente.
- Humanização: Mostra pessoas reais, empatia e proximidade.

CATEGORIA: Atributo + Performance
- Status: Valorização social ou profissional indireta.
- Diferenciação: Característica única que foge do padrão.
- Validação Externa: Reconhecimento pelo mercado ou órgãos reguladores.

CATEGORIA: Oferta
- Ancoragem de Preço: Comparação com preço anterior ou valor “real” maior.
- Inclusão: Bolsas de até 100% para estudar.
- Acessibilidade Financeira: Mostra que “cabe no bolso” (parcelas, valores baixos).
- Benefício Extra: Algo a mais sem custo (isenção, bônus, vantagem).

CATEGORIA: Oferta + Performance
- Custo de Oportunidade: Destaca o que a pessoa perde ao não agir agora.

CATEGORIA: Oferta + Atributo
- Autonomia e Inclusão: Bolsas de até 100% para estudar de onde e como quiser.

CATEGORIA: Performance
- Escassez: Poucas vagas, tempo limitado ou benefício que acaba logo.
- FOMO: Aversão à perda.
- Urgência: Pressão temporal clara para decisão imediata.
- Facilidade: Processo simples, sem burocracia ou esforço.
- Exclusividade: Oferta válida apenas para um grupo específico.
- Previsibilidade: Caminho claro do início ao resultado final.
- Comparativo de Performance: Mostra desempenho superior frente à média do mercado.

CATEGORIA: Performance + Atributo
- Risco Zero: Garantias, cancelamento fácil, sem compromisso inicial.
- Comparação Direta: Mostra que a oferta é melhor que alternativas comuns.
- Consistência: Resultados repetidos ao longo do tempo.

CATEGORIA: Performance + Oferta
- Evidência Numérica: Percentuais, rankings, volumes, tempo médio.
`;

const getPlatformBestPractices = (platform: Platform) => {
  switch (platform) {
    case 'Meta':
      return "FOCO EM META (Facebook/Instagram): Priorize o 'Stop the Scroll'. Use headlines curtas e de impacto. Foque em prova social e conexão visual. A copy deve ser direta e emocional.";
    case 'Google':
      return "FOCO EM GOOGLE (Search/Display): Priorize clareza, intenção de busca e palavras-chave. Destaque benefícios imediatos, credibilidade e extensões de oferta. A copy deve ser informativa e confiável.";
    case 'TikTok':
      return "FOCO EM TIKTOK: Seja autêntico e 'nativo'. O conteúdo deve parecer entretenimento, não anúncio. Foque em ganchos rápidos (primeiros 3 segundos), humanização e tendências. Use linguagem ágil.";
    case 'SITES/CRM':
      return "FOCO EM SITES/CRM/EMAIL: Priorize retenção, profundidade de informação e confiança. A copy deve ser estruturada para leitura (scannable), com CTAs claros e argumentos robustos de conversão. Foque em CRM personalizado e fluxos de nutrição.";
    default:
      return "Foque em boas práticas gerais de marketing digital e conversão.";
  }
};

