  switch (brand) {
    case 'Anhanguera': return "sites oficiais anhanguera.com e blog.anhanguera.com";
    case 'Unopar': return "site oficial unopar.com.br";
    case 'Unime': return "site oficial unime.edu.br";
    case 'Pitágoras': return "site oficial pitagoras.com.br";
    case 'Unic': return "site oficial unic.com.br";
    case 'Uniderp': return "site oficial uniderp.com.br";
    case 'Anglo': return "site oficial portalanglo.com.br";
    case 'Singularidades': return "site oficial singularidades.com.br";
    case 'Red Balloon': return "site oficial redballoon.com.br";
    default: return `site oficial da marca ${brand}`;
  }
};

export const analyzeCreative = async (
  base64Image: string | null, 
  mimeType: string, 
  copyText: string, 
  platform: Platform
): Promise<AnalysisResult> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const platformPractices = getPlatformBestPractices(platform);

  const parts: any[] = [
    { text: `${KNOWLEDGE_BASE_PROMPT}

BOAS PRÁTICAS DA PLATAFORMA:
${platformPractices}

Analise a peça (Imagem e/ou Texto da Copy) considerando o contexto da plataforma ${platform}. 
Extraia os 2 pilares (gatilhos/atributos) mais fortes de acordo com a taxonomia.
Sugira também 3 opções de CTA (Call to Action) específicas e nativas para ${platform}.

Texto da Copy: "${copyText}"` }
  ];

  if (base64Image) {
    parts.push({
      inlineData: {
        data: base64Image.split(',')[1],
        mimeType: mimeType,
      },
    });
  }

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: { parts },
    config: {
      temperature: 0.15,
      seed: 42,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          score: { type: Type.NUMBER },
          summary: { type: Type.STRING },
          suggestedCTAs: {
            type: Type.ARRAY,
            items: { type: Type.STRING },
            minItems: 3,
            maxItems: 3
          },
          foundItems: {
            type: Type.ARRAY,
            minItems: 2,
            maxItems: 2,
            items: {
              type: Type.OBJECT,
              properties: {
                category: { type: Type.STRING },
                name: { type: Type.STRING },
                intensity: { type: Type.NUMBER },
                officialDescription: { type: Type.STRING },
                analysis: { type: Type.STRING },
                evidence: { type: Type.STRING }
              },
              required: ["category", "name", "intensity", "officialDescription", "analysis", "evidence"]
            }
          },
          improvements: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          }
        },
        required: ["score", "summary", "foundItems", "improvements", "suggestedCTAs"]
      }
    }
  });

  const resultText = response.text;
  if (!resultText) throw new Error("A IA não retornou um diagnóstico válido.");

  return JSON.parse(resultText) as AnalysisResult;
};

export const suggestNewCopys = async (
  originalAnalysis: AnalysisResult,
  originalCopy: string,
  platform: Platform,
  brand: Brand
): Promise<{ suggestions: SuggestedCopy[], sources: GroundingSource[] }> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const detectedPillars = originalAnalysis.foundItems.map(i => `${i.name} (${i.category})`).join(", ");
  const brandKnowledgeBase = getBrandSpecificContext(brand);
  const platformPractices = getPlatformBestPractices(platform);

  const prompt = `${KNOWLEDGE_BASE_PROMPT}

DIRETRIZ DE MARCA:
Utilize as diretrizes da marca: ${brand}. Consulte o ${brandKnowledgeBase}.

BOAS PRÁTICAS DA PLATAFORMA:
${platformPractices}

Instrução:
Com base no texto original ("${originalCopy}"), crie 3 variações que otimizem os gatilhos identificados (${detectedPillars}) e sigam as boas práticas de ${platform}.
Respeite rigorosamente o tom de voz e as referências de mercado da ${brand}.

Copy original: "${originalCopy}"

Retorne APENAS JSON: {"suggestions": [{"trigger": "", "category": "", "text": "", "reasoning": ""}]}`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      temperature: 0.3,
      seed: 42,
      tools: [{ googleSearch: {} }]
    }
  });

  const responseText = response.text || "";
  const jsonMatch = responseText.match(/\{[\s\S]*\}/);
  const jsonStr = jsonMatch ? jsonMatch[0] : responseText;

  let suggestions: SuggestedCopy[] = [];
  try {
    const parsed = JSON.parse(jsonStr);
    suggestions = parsed.suggestions || [];
  } catch (e) {
    console.error("JSON parse error:", e);
  }

  const sources: GroundingSource[] = [];
  const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
  if (chunks) {
    chunks.forEach((chunk: any) => {
      if (chunk.web?.uri) {
        sources.push({
          title: chunk.web.title || `Fonte ${brand}`,
          uri: chunk.web.uri
        });
      }
    });
  }

  return { suggestions, sources };
};

