      if (brandMenuRef.current && !brandMenuRef.current.contains(event.target as Node)) {
        setIsBrandMenuOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    const checkAvailability = async () => {
      // @ts-ignore
      if (window.aistudio) {
        try {
          // @ts-ignore
          const hasKey = await window.aistudio.hasSelectedApiKey();
          setIsAuthenticated(hasKey);
        } catch (e) {
          setIsAuthenticated(false);
        }
      } else if (process.env.API_KEY) {
        setIsAuthenticated(true);
      } else {
        setIsAuthenticated(false);
      }
    };
    checkAvailability();
  }, []);

  const handleGoogleLogin = async () => {
    setError(null);
    setIsLoggingIn(true);
    try {
      // @ts-ignore
      if (window.aistudio && typeof window.aistudio.openSelectKey === 'function') {
        // @ts-ignore
        await window.aistudio.openSelectKey();
        // Assume sucesso após abrir o diálogo conforme diretrizes
        setIsAuthenticated(true);
      } else {
        // Fallback para ambiente local se houver chave no env
        if (process.env.API_KEY) {
          setIsAuthenticated(true);
        } else {
          throw new Error("O seletor de conta Google não pôde ser aberto.");
        }
      }
    } catch (err: any) {
      setError(err.message || "Erro ao conectar com Google.");
    } finally {
      setIsLoggingIn(false);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (!file.type.startsWith('image/')) {
        setError("Por favor, selecione uma imagem.");
        return;
      }
      setMimeType(file.type);
      const reader = new FileReader();
      reader.onloadend = () => {
        setImage(reader.result as string);
        setError(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAnalyze = async () => {
    if (!image && !copyText) {
      setError("Insira o texto ou uma imagem para análise.");
      return;
    }

    setStatus(AnalysisStatus.LOADING);
    setError(null);
    setResult(null);

