  const platformPractices = getPlatformBestPractices(platform);

  const prompt = `${KNOWLEDGE_BASE_PROMPT}

CONTEXTO DA PLATAFORMA:
${platformPractices}

INSTRUÇÕES DE ANÁLISE:
1. Analise a copy e a imagem (se fornecida).
2. Extraia os 2 gatilhos/atributos mais dominantes.
3. Gere um SCORE de eficácia de 0 a 100 (onde 100 é um anúncio perfeito para a plataforma).
4. Crie 3 CTAs altamente CONTEXTUALIZADOS. Não use apenas "Clique Aqui". 
   Ex: Se for Anhanguera falando de bolsa, use "Garanta sua bolsa Anhanguera" ou "Consultar desconto de 100%".
5. Forneça um resumo executivo e pontos de melhoria.

Texto da Copy fornecido: "${copyText}"`;

  const contents: any = { parts: [{ text: prompt }] };
  if (base64Image) {
    contents.parts.push({
      inlineData: {
        data: base64Image.split(',')[1],
        mimeType: mimeType,
      },
    });
  }

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents,
    config: {
      temperature: 0.1,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          score: { type: Type.INTEGER, description: "Percentual de 0 a 100" },
          summary: { type: Type.STRING },
          suggestedCTAs: {
            type: Type.ARRAY,
            items: { type: Type.STRING },
            description: "CTAs específicos baseados no texto e marca",
            minItems: 3,
            maxItems: 3
          },
          foundItems: {
            type: Type.ARRAY,
            minItems: 2,
            maxItems: 2,
            items: {
              type: Type.OBJECT,
              properties: {
                category: { type: Type.STRING },
                name: { type: Type.STRING },
                intensity: { type: Type.NUMBER, description: "1-10" },
                officialDescription: { type: Type.STRING },
                analysis: { type: Type.STRING },
                evidence: { type: Type.STRING }
              },
              required: ["category", "name", "intensity", "officialDescription", "analysis", "evidence"]
            }
          },
          improvements: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          }
        },
        required: ["score", "summary", "foundItems", "improvements", "suggestedCTAs"]
      }
    }
  });

  if (!response.text) throw new Error("A IA não retornou um diagnóstico.");
  return JSON.parse(response.text) as AnalysisResult;
};

export const suggestNewCopys = async (
  originalAnalysis: AnalysisResult,
  originalCopy: string,
  platform: Platform,
  brand: Brand
): Promise<{ suggestions: SuggestedCopy[], sources: GroundingSource[] }> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const detectedPillars = originalAnalysis.foundItems.map(i => `${i.name}`).join(", ");

  const prompt = `${KNOWLEDGE_BASE_PROMPT}

MARCA: ${brand}
CANAL: ${platform}
GATILHOS A EXPLORAR: ${detectedPillars}

Crie 3 variações de copy otimizadas. Cada variação deve focar em um ângulo diferente, mantendo o tom de voz da marca ${brand} e as diretrizes de ${platform}.

Copy original: "${originalCopy}"

Retorne JSON: {"suggestions": [{"trigger": "", "category": "", "text": "", "reasoning": ""}]}`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      temperature: 0.7,
      tools: [{ googleSearch: {} }]
    }
  });

  const responseText = response.text || "";
  const jsonMatch = responseText.match(/\{[\s\S]*\}/);
  const jsonStr = jsonMatch ? jsonMatch[0] : responseText;

  let suggestions: SuggestedCopy[] = [];
  try {
    const parsed = JSON.parse(jsonStr);
    suggestions = parsed.suggestions || [];
  } catch (e) {
    console.error("Erro no parse:", e);
  }

  const sources: GroundingSource[] = [];
  const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
  if (chunks) {
    chunks.forEach((chunk: any) => {
      if (chunk.web?.uri) {
        sources.push({ title: chunk.web.title || "Referência", uri: chunk.web.uri });
      }
    });
  }

  return { suggestions, sources };
};

