import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult, SuggestedCopy, GroundingSource, Brand, Platform } from "../types";

const KNOWLEDGE_BASE_PROMPT = `
Você é um estrategista sênior de publicidade e especialista em copywriting.
Sua análise deve ser baseada ESTRITAMENTE na seguinte taxonomia:

CATEGORIA: Atributo
- Prova Social, Autoridade, Resultados Concretos, Casos Reais, Eficiência, Credibilidade, Segurança, Qualidade Percebida, Pertencimento, Identificação, Confiabilidade, Clareza, Humanização.

CATEGORIA: Atributo + Performance
- Status, Diferenciação, Validação Externa.

CATEGORIA: Oferta
- Ancoragem de Preço, Inclusão, Acessibilidade Financeira, Benefício Extra.

CATEGORIA: Oferta + Performance
- Custo de Oportunidade.

CATEGORIA: Oferta + Atributo
- Autonomia e Inclusão.

CATEGORIA: Performance
- Escassez, FOMO, Urgência, Facilidade, Exclusividade, Previsibilidade, Comparativo de Performance.

CATEGORIA: Performance + Atributo
- Risco Zero, Comparação Direta, Consistência.

CATEGORIA: Performance + Oferta
- Evidência Numérica.
`;

const getPlatformBestPractices = (platform: Platform) => {
  switch (platform) {
    case 'Meta': return "Plataforma: Meta (FB/IG). Foco: Emoção, ganchos visuais e CTAs persuasivos que gerem cliques imediatos.";
    case 'Google': return "Plataforma: Google Ads. Foco: Intenção de busca, clareza absoluta e CTAs de conversão direta.";
    case 'TikTok': return "Plataforma: TikTok. Foco: Autenticidade, entretenimento e ganchos ultra-rápidos nos primeiros 2 segundos.";
    case 'SITES/CRM': return "Plataforma: Sites/CRM. Foco: Detalhamento, confiança e CTAs de fechamento de funil.";
    default: return "";
  }
};

export const analyzeCreative = async (
  base64Image: string | null, 
  mimeType: string, 
  copyText: string, 
  platform: Platform
): Promise<AnalysisResult> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const platformPractices = getPlatformBestPractices(platform);

  const prompt = `${KNOWLEDGE_BASE_PROMPT}

CONTEXTO DA PLATAFORMA:
${platformPractices}

INSTRUÇÕES DE ANÁLISE:
1. Analise o texto e a imagem do anúncio.
2. Identifique os 2 gatilhos mentais mais fortes.
3. Atribua um SCORE de eficácia de 0 a 100 (número inteiro).
4. Sugira 3 CTAs altamente personalizados que referenciem diretamente o conteúdo da copy (Ex: se a copy fala de bolsa, use "Quero minha Bolsa").
5. Explique a evidência de cada gatilho baseando-se no que foi lido/visto.

Texto do anúncio: "${copyText}"`;

  const contents: any = { parts: [{ text: prompt }] };
  if (base64Image) {
    contents.parts.push({
      inlineData: {
        data: base64Image.split(',')[1],
        mimeType: mimeType,
      },
    });
  }

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents,
    config: {
      temperature: 0.1,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          score: { type: Type.INTEGER, description: "Eficácia de 0 a 100" },
          summary: { type: Type.STRING },
          suggestedCTAs: {
            type: Type.ARRAY,
            items: { type: Type.STRING },
            minItems: 3,
            maxItems: 3
          },
          foundItems: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                category: { type: Type.STRING },
                name: { type: Type.STRING },
                intensity: { type: Type.NUMBER },
                officialDescription: { type: Type.STRING },
                analysis: { type: Type.STRING },
                evidence: { type: Type.STRING }
              },
              required: ["category", "name", "intensity", "officialDescription", "analysis", "evidence"]
            }
          },
          improvements: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          }
        },
        required: ["score", "summary", "foundItems", "improvements", "suggestedCTAs"]
      }
    }
  });

  if (!response.text) throw new Error("A IA não retornou um diagnóstico.");
  return JSON.parse(response.text) as AnalysisResult;
};

export const suggestNewCopys = async (
  originalAnalysis: AnalysisResult,
  originalCopy: string,
  platform: Platform,
  brand: Brand
): Promise<{ suggestions: SuggestedCopy[], sources: GroundingSource[] }> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const detectedPillars = originalAnalysis.foundItems.map(i => i.name).join(", ");

  const prompt = `${KNOWLEDGE_BASE_PROMPT}

MARCA: ${brand}
CANAL: ${platform}
GATILHOS PARA REFORÇAR: ${detectedPillars}

Gere 3 variações de copy baseadas no texto original, otimizando os gatilhos para a plataforma ${platform} e respeitando o tom de voz da marca ${brand}.

Texto original: "${originalCopy}"

Retorne JSON: {"suggestions": [{"trigger": "", "category": "", "text": "", "reasoning": ""}]}`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      temperature: 0.7,
      tools: [{ googleSearch: {} }]
    }
  });

  const responseText = response.text || "";
  const jsonMatch = responseText.match(/\{[\s\S]*\}/);
  const jsonStr = jsonMatch ? jsonMatch[0] : responseText;

  let suggestions: SuggestedCopy[] = [];
  try {
    const parsed = JSON.parse(jsonStr);
    suggestions = parsed.suggestions || [];
  } catch (e) {
    console.error("Erro no parse das sugestões.");
  }

  const sources: GroundingSource[] = [];
  const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
  if (chunks) {
    chunks.forEach((chunk: any) => {
      if (chunk.web?.uri) {
        sources.push({ title: chunk.web.title || "Referência Oficial", uri: chunk.web.uri });
      }
    });
  }

  return { suggestions, sources };
};

