import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult, Brand, Platform } from "../types";

const KNOWLEDGE_BASE_PROMPT = `
Você é um estrategista sênior de publicidade e especialista em copywriting de alta performance.
Sua análise deve ser baseada ESTRITAMENTE na seguinte taxonomia de gatilhos e atributos:

CATEGORIA: Atributo
- Prova Social, Autoridade, Resultados Concretos, Casos Reais, Eficiência, Credibilidade, Segurança, Qualidade Percebida, Pertencimento, Identificação, Confiabilidade, Clareza, Humanização.

CATEGORIA: Atributo + Performance
- Status, Diferenciação, Validação Externa.

CATEGORIA: Oferta
- Ancoragem de Preço, Inclusão, Acessibilidade Financeira, Benefício Extra.

CATEGORIA: Oferta + Performance
- Custo de Oportunidade.

CATEGORIA: Oferta + Atributo
- Autonomia e Inclusão.

CATEGORIA: Performance
- Escassez, FOMO, Urgência, Facilidade, Exclusividade, Previsibilidade, Comparativo de Performance.

CATEGORIA: Performance + Atributo
- Risco Zero, Comparação Direta, Consistência.

CATEGORIA: Performance + Oferta
- Evidência Numérica.
`;

const getPlatformBestPractices = (platform: Platform) => {
  switch (platform) {
    case 'Meta': return "Plataforma: Meta (Facebook/Instagram). Foco: Interrupção de padrão via copy impactante, apelo emocional e CTAs de engajamento direto.";
    case 'Google': return "Plataforma: Google Ads. Foco: Intencionalidade, clareza absoluta nos benefícios e CTAs de ação direta.";
    case 'TikTok': return "Plataforma: TikTok. Foco: Autenticidade, linguagem falada e ganchos rápidos no texto.";
    case 'SITES/CRM': return "Plataforma: Sites, Landing Pages ou CRM. Foco: Retenção, aprofundamento de confiança e CTAs de fechamento de ciclo.";
    default: return "";
  }
};

export const analyzeCreative = async (
  copyText: string, 
  platform: Platform
): Promise<AnalysisResult> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const platformPractices = getPlatformBestPractices(platform);

  const prompt = `${KNOWLEDGE_BASE_PROMPT}

CONTEXTO DO CANAL DE MÍDIA:
${platformPractices}

INSTRUÇÕES DE ANÁLISE:
1. Avalie detalhadamente o texto da copy enviada.
2. Identifique os 2 pilares (gatilhos/atributos) dominantes na redação.
3. Calcule um SCORE de eficácia (0 a 100) baseado no poder de persuasão e clareza da oferta para a plataforma ${platform}.
4. SUGIRA 3 CTAs: Eles devem ser altamente contextualizados com a copy fornecida. Não use apenas termos genéricos. 
5. Forneça evidências textuais para cada gatilho encontrado.

Copy do Anúncio: "${copyText}"`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      temperature: 0.1,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          score: { type: Type.INTEGER },
          summary: { type: Type.STRING },
          suggestedCTAs: {
            type: Type.ARRAY,
            items: { type: Type.STRING },
            minItems: 3,
            maxItems: 3
          },
          foundItems: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                category: { type: Type.STRING },
                name: { type: Type.STRING },
                intensity: { type: Type.NUMBER },
                officialDescription: { type: Type.STRING },
                analysis: { type: Type.STRING },
                evidence: { type: Type.STRING }
              },
              required: ["category", "name", "intensity", "officialDescription", "analysis", "evidence"]
            }
          },
          improvements: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          }
        },
        required: ["score", "summary", "foundItems", "improvements", "suggestedCTAs"]
      }
    }
  });

  if (!response.text) throw new Error("Falha na resposta da IA.");
  return JSON.parse(response.text) as AnalysisResult;
};

