import React, { useState } from 'react';
import { GoogleGenAI, Type } from "@google/genai";
import { 
  Palette, 
  Sparkles, 
  Loader2, 
  Camera, 
  Type as TypeIcon, 
  Layers, 
  Copy, 
  AlertCircle,
  Zap,
  Eye,
  Monitor
} from 'lucide-react';
import { Brand } from '../types';

interface DesignerResult {
  visualDirection: string;
  colorPalette: { hex: string; name: string; psychology: string }[];
  compositionTips: string[];
  imagePrompt: string;
  psychologicalImpact: string;
}

const DesignerArea: React.FC<{ selectedBrand: Brand }> = ({ selectedBrand }) => {
  const [concept, setConcept] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [result, setResult] = useState<DesignerResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  const generateVisualDirection = async () => {
    if (!concept.trim()) return;
    setIsLoading(true);
    setError(null);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `Você é um Diretor de Arte sênior. Baseado no conceito criativo abaixo para a marca ${selectedBrand}, gere uma direção visual completa.

      CONCEITO: "${concept}"

      Forneça:
      1. Direção Visual Geral.
      2. Uma paleta de 4 cores (HEX, Nome, Psicologia).
      3. 3 Dicas de Composição.
      4. Um prompt otimizado para Midjourney/DALL-E.
      5. O impacto psicológico visual esperado.`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              visualDirection: { type: Type.STRING },
              colorPalette: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    hex: { type: Type.STRING },
                    name: { type: Type.STRING },
                    psychology: { type: Type.STRING }
                  },
                  required: ["hex", "name", "psychology"]
                }
              },
              compositionTips: { type: Type.ARRAY, items: { type: Type.STRING } },
              imagePrompt: { type: Type.STRING },
              psychologicalImpact: { type: Type.STRING }
            },
            required: ["visualDirection", "colorPalette", "compositionTips", "imagePrompt", "psychologicalImpact"]
          }
        }
      });

      if (!response.text) throw new Error("Erro na IA");
      setResult(JSON.parse(response.text));
    } catch (err) {
      setError("Falha ao gerar direção visual. Verifique sua conexão.");
    } finally {
      setIsLoading(false);
    }
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
  };

  return (
    <main className="flex-grow max-w-7xl mx-auto w-full px-6 py-10 grid grid-cols-1 xl:grid-cols-12 gap-10 animate-in fade-in duration-500">
      <div className="xl:col-span-5 space-y-6">
        <div className="bg-white rounded-[2rem] p-8 shadow-sm border border-slate-100 sticky top-24">
          <div className="flex items-center gap-3 mb-6">
            <div className="bg-indigo-50 p-2 rounded-xl">
              <Palette className="text-indigo-600 w-5 h-5" />
            </div>
            <div>
              <h2 className="text-lg font-black tracking-tight">Visual Hook Generator</h2>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Direção de Arte Assistida</p>
            </div>
          </div>

          <div className="mb-8">
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 block">Conceito da Campanha ou Idea</label>
            <textarea 
              className="w-full bg-slate-50 border border-slate-100 rounded-2xl p-5 text-sm focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-600 outline-none transition-all min-h-[180px]" 
              placeholder="Ex: Campanha de volta às aulas focada em tecnologia e futuro para jovens de baixa renda..." 
              value={concept} 
              onChange={(e) => setConcept(e.target.value)} 
            />
          </div>

          <div className="space-y-4">
             <div className="bg-indigo-50/50 rounded-2xl p-4 border border-indigo-100/50">
                <p className="text-[10px] text-indigo-600 font-bold uppercase tracking-widest flex items-center gap-2 mb-2">
                   <Zap className="w-3.5 h-3.5" /> Estilo de Marca: {selectedBrand}
                </p>
                <p className="text-[11px] text-indigo-900/60 leading-relaxed font-medium italic">
                   A IA irá considerar os guias de marca da {selectedBrand} para gerar uma paleta e estilo que respeitem a identidade visual atual.
                </p>
             </div>

            {error && <div className="p-4 bg-red-50 border border-red-100 rounded-xl text-red-600 text-[11px] font-bold flex gap-2"><AlertCircle className="w-4 h-4 flex-shrink-0" />{error}</div>}

            <button 
              onClick={generateVisualDirection} 
              disabled={isLoading || !concept.trim()} 
              className={`w-full py-5 rounded-2xl font-black text-xs uppercase tracking-[0.2em] flex items-center justify-center gap-3 transition-all active:scale-[0.98] shadow-xl ${isLoading || !concept.trim() ? 'bg-slate-100 text-slate-400' : 'bg-slate-900 text-white hover:bg-slate-800 shadow-slate-200'}`}
            >
              {isLoading ? <Loader2 className="w-5 h-5 animate-spin" /> : <><Sparkles className="w-5 h-5" /> Gerar Direção Visual</>}
            </button>
          </div>
        </div>
      </div>

      <div className="xl:col-span-7">
