              <div className={`p-2 rounded-xl ${hasLowIntensity ? 'bg-amber-100 text-amber-600' : 'bg-indigo-100 text-indigo-600'}`}>
                <Zap className="w-5 h-5" />
              </div>
              <div>
                <h3 className="text-lg font-black text-slate-900 tracking-tight">Variações de Alta Intensidade</h3>
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Upgrade para Intensidade Máxima (9-10)</p>
              </div>
            </div>
            {hasLowIntensity && (
               <div className="px-3 py-1 bg-amber-50 text-amber-700 rounded-full text-[9px] font-black uppercase tracking-tighter border border-amber-100 animate-pulse">
                 Ajuste Necessário
               </div>
            )}
          </div>

          <div className="space-y-6">
            {data.suggestedCopys.map((copy, idx) => (
              <div key={idx} className="group bg-slate-50 hover:bg-white border border-slate-100 hover:border-indigo-200 hover:shadow-lg rounded-2xl p-6 transition-all relative overflow-hidden">
