                <path d="M12.48 10.92v3.28h7.84c-.24 1.84-.908 3.152-1.928 4.176-1.288 1.288-3.312 2.696-6.912 2.696-5.832 0-10.432-4.712-10.432-10.544s4.6-10.544 10.432-10.544c3.136 0 5.392 1.24 7.08 2.84l2.32-2.32c-2.032-1.944-5.048-3.424-9.4-3.424-8.08 0-14.736 6.552-14.736 14.64s6.656 14.64 14.736 14.64c4.352 0 7.64-1.432 10.224-4.12 2.664-2.664 3.504-6.424 3.504-9.44 0-.896-.08-1.744-.224-2.52h-13.52z"/>
              </svg>
