const KNOWLEDGE_BASE_PROMPT = `
Você é um estrategista sênior de publicidade e especialista em copywriting de alta performance.
Sua análise deve ser baseada ESTRITAMENTE na taxonomia de gatilhos abaixo e nas DIRETRIZES DE MULTICANALIDADE (baseadas no Guia oficial):

--- TAXONOMIA DE GATILHOS ---
CATEGORIA: Atributo
- Prova Social, Autoridade, Resultados Concretos, Casos Reais, Eficiência, Credibilidade, Segurança, Qualidade Percebida, Pertencimento, Identificação, Confiabilidade, Clareza, Humanização.

CATEGORIA: Atributo + Performance
- Status, Diferenciação, Validação Externa.

CATEGORIA: Oferta
- Ancoragem de Preço, Inclusão, Acessibilidade Financeira, Benefício Extra.

CATEGORIA: Oferta + Performance
- Custo de Oportunidade.

CATEGORIA: Oferta + Atributo
- Autonomia e Inclusão.

CATEGORIA: Performance
- Escassez, FOMO, Urgência, Facilidade, Exclusividade, Previsibilidade, Comparativo de Performance.

CATEGORIA: Performance + Atributo
- Risco Zero, Comparação Direta, Consistência.

CATEGORIA: Performance + Oferta
- Evidência Numérica.

--- DIRETRIZES DE MULTICANALIDADE (GUIA DE REFERÊNCIA) ---

1. META ADS:
- Objetivo: Parar o scroll.
- Especificações: Headline (até 40 chars), Primary Text (até 125 chars para melhor performance mobile).
- Comportamento: Rápido, distraído, multitarefa.
- Técnica: Hook forte nas 3 primeiras palavras. Gatilhos: Urgência, Escassez, Prova Social.

2. GOOGLE ADS (SEARCH):
- Objetivo: Capturar intenção ativa.
- Especificações: Headlines 1 e 2 (30 chars cada), Description (90 chars).
- Comportamento: Busca objetiva, quer resposta rápida.
- Técnica: Inclua palavra-chave. Foque em diferencial competitivo (preço, rapidez, autoridade). Números tendem a ter maior CTR.

3. YOUTUBE ADS / ROTEIRO:
- Objetivo: Reter atenção nos primeiros segundos.
- Especificações: Hook visual+fala nos primeiros 5s. Título apoio (25 chars), Descrição (35-100 chars).
- Técnica: Use perguntas no início ("Já pensou em...?"). Depoimentos reais ou cenas aspiracionais.

4. SITES/CRM/GERAL:
- Foco em retenção, clareza de valor e aprofundamento de confiança.
`;

const getPlatformBestPractices = (platform: Platform) => {
  switch (platform) {
    case 'Meta': return "Plataforma: Meta Ads. FOCO: Scroll stop e urgência. LIMITE: Headline 40, Primary 125.";
    case 'Google': return "Plataforma: Google Ads. FOCO: Intenção ativa e palavras-chave. LIMITE: Headlines 30, Desc 90.";
    case 'SITES/CRM': return "Plataforma: Sites/CRM. FOCO: Retenção e clareza de valor.";
    case 'Roteiro': return "Formato: Roteiro (YouTube/Vídeo). FOCO: Gancho nos primeiros 5s e CTA direto.";
    default: return "";
  }
};

export const analyzeCreative = async (
  copyText: string, 
  platform: Platform
): Promise<AnalysisResult> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const platformPractices = getPlatformBestPractices(platform);

  const prompt = `${KNOWLEDGE_BASE_PROMPT}

CONTEXTO DO CANAL DE MÍDIA SELECIONADO:
${platformPractices}

INSTRUÇÕES DE ANÁLISE:
1. Avalie detalhadamente o texto enviado com base nas especificações técnicas de ${platform}.
2. Identifique os 2 pilares (gatilhos/atributos) dominantes.
3. Calcule o SCORE (0-100) considerando o alinhamento com as boas práticas.
4. SUGIRA 3 CTAs contextualizados.
5. REGRA CRÍTICA PARA VARIAÇÕES: 
   - Se algum dos gatilhos principais identificados tiver intensidade MENOR QUE 8, você deve OBRIGATORIAMENTE gerar 3 sugestões de copy em 'suggestedCopys'.
   - Estas sugestões DEVEM focar ÚNICA E EXCLUSIVAMENTE em elevar a intensidade do(s) gatilho(s) que estão fracos (abaixo de 8). 
   - Não sugira variações baseadas em gatilhos que já estão fortes (>=8), a menos que todos os gatilhos já estejam fortes.
   - Cada variação deve ser rotulada com o nome do gatilho que está sendo corrigido no campo 'trigger'.
   - Respeite rigorosamente os limites de caracteres de ${platform} em cada sugestão.

Texto Enviado: "${copyText}"`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      temperature: 0.1,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          score: { type: Type.INTEGER },
          summary: { type: Type.STRING },
          suggestedCTAs: {
            type: Type.ARRAY,
            items: { type: Type.STRING },
            minItems: 3,
            maxItems: 3
          },
          foundItems: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                category: { type: Type.STRING },
                name: { type: Type.STRING },
                intensity: { type: Type.NUMBER },
                officialDescription: { type: Type.STRING },
                analysis: { type: Type.STRING },
                evidence: { type: Type.STRING }
              },
              required: ["category", "name", "intensity", "officialDescription", "analysis", "evidence"]
            }
          },
          suggestedCopys: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                trigger: { type: Type.STRING, description: "O nome do gatilho que estava fraco e está sendo potencializado." },
                category: { type: Type.STRING },
                text: { type: Type.STRING },
                reasoning: { type: Type.STRING }
              },
              required: ["trigger", "category", "text", "reasoning"]
            }
          },
          improvements: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          }
        },
        required: ["score", "summary", "foundItems", "improvements", "suggestedCTAs", "suggestedCopys"]
      }
    }
  });

  if (!response.text) throw new Error("Falha na resposta da IA.");
  return JSON.parse(response.text) as AnalysisResult;
};

