            },
            foundItems: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  category: { type: Type.STRING },
                  name: { type: Type.STRING },
                  intensity: { type: Type.NUMBER },
                  officialDescription: { type: Type.STRING },
                  analysis: { type: Type.STRING },
                  evidence: { type: Type.STRING }
                },
                required: ["category", "name", "intensity", "officialDescription", "analysis", "evidence"]
              },
              minItems: 2,
              maxItems: 2
            },
            suggestedCopys: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  trigger: { type: Type.STRING },
                  category: { type: Type.STRING },
                  text: { type: Type.STRING },
                  reasoning: { type: Type.STRING }
                },
                required: ["trigger", "category", "text", "reasoning"]
              },
              minItems: 3
            },
            improvements: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          },
          required: ["score", "summary", "foundItems", "improvements", "suggestedCTAs", "suggestedCopys"]
        }
      }
    });

    const responseText = response.text;
    if (!responseText) {
      console.error("Gemini API retornou uma resposta vazia ou bloqueada.");
      throw new Error("A IA não conseguiu gerar uma resposta válida para este texto.");
    }

    try {
      return JSON.parse(responseText.trim()) as AnalysisResult;
    } catch (parseError) {
      console.error("Erro ao processar JSON da IA:", responseText);
      throw new Error("Erro de formatação na resposta da análise.");
    }
  } catch (apiError: any) {
    console.error("Erro na chamada da Gemini API:", apiError);
    throw apiError;
  }
};

