  const strokeWidth = 10;
  const normalizedRadius = radius - strokeWidth / 2;
  const circumference = normalizedRadius * 2 * Math.PI;
  const strokeDashoffset = circumference - (data.score / 100) * circumference;

  const lowIntensityItems = data.foundItems.filter(item => item.intensity < 8);
  const hasLowIntensity = lowIntensityItems.length > 0;

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700 pb-20">
      {/* Score Section */}
      <div className="bg-white rounded-3xl shadow-sm border border-slate-200 p-8 flex flex-col md:flex-row items-center gap-8">
        <div className="relative flex-shrink-0 w-32 h-32">
          <svg viewBox="0 0 104 104" className="w-full h-full transform -rotate-90 drop-shadow-sm">
            <circle cx="52" cy="52" r={normalizedRadius} stroke="currentColor" strokeWidth={strokeWidth} fill="transparent" className="text-slate-100" />
            <circle cx="52" cy="52" r={normalizedRadius} stroke="currentColor" strokeWidth={strokeWidth} fill="transparent" strokeDasharray={circumference} style={{ strokeDashoffset }} className="text-indigo-600 transition-all duration-1000 ease-out" strokeLinecap="round" />
          </svg>
          <div className="absolute inset-0 flex flex-col items-center justify-center">
            <span className="text-3xl font-black text-slate-800 leading-none">{data.score}</span>
            <span className="text-[10px] uppercase font-bold text-slate-400 mt-1">Eficácia</span>
          </div>
        </div>
        <div className="flex-grow">
          <div className="flex items-center gap-2 mb-1 text-indigo-600">
            <Layers className="w-4 h-4" />
            <span className="text-[10px] font-bold uppercase tracking-widest">Análise de Gatilhos</span>
          </div>
          <h2 className="text-xl font-bold text-slate-900 mb-2">Diagnóstico Criativo</h2>
          <p className="text-slate-600 leading-relaxed text-sm">{data.summary}</p>
        </div>
      </div>

      {/* Pillars Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {data.foundItems.slice(0, 2).map((item, idx) => (
          <div key={idx} className={`bg-white rounded-3xl border overflow-hidden shadow-sm flex flex-col transition-all ${item.intensity < 8 ? 'border-amber-200 ring-2 ring-amber-50' : 'border-slate-200'}`}>
            <div className="px-6 py-4 flex flex-col gap-1" style={{ backgroundColor: `${getCategoryColor(item.category)}10` }}>
              <div className="flex justify-between items-center">
                <span className="text-[10px] font-black uppercase tracking-[0.2em]" style={{ color: getCategoryColor(item.category) }}>{item.category}</span>
                {item.intensity < 8 && (
                  <div className="flex items-center gap-1.5 text-[8px] bg-amber-100 text-amber-600 px-2 py-0.5 rounded font-black uppercase tracking-widest border border-amber-200">
                    <AlertCircle className="w-2.5 h-2.5" />
                    Baixa Intensidade
                  </div>
                )}
              </div>
              <h3 className="text-lg font-black text-slate-800">{item.name}</h3>
            </div>

            <div className="p-6 flex-grow space-y-4">
              <div className="flex items-start gap-2 text-slate-500">
                <Info className="w-3.5 h-3.5 mt-0.5 flex-shrink-0 text-slate-300" />
                <p className="text-[11px] italic leading-tight">{item.officialDescription}</p>
              </div>

              <div className="space-y-1">
                <div className="flex justify-between text-[9px] font-bold text-slate-400 uppercase">
                  <span>Intensidade Atual</span>
                  <span className={item.intensity < 8 ? 'text-amber-500 font-black' : ''}>{item.intensity}/10</span>
                </div>
                <div className="h-1.5 w-full bg-slate-100 rounded-full overflow-hidden">
                  <div className={`h-full transition-all duration-1000 ease-out ${item.intensity < 8 ? 'bg-amber-400' : ''}`} style={{ width: `${item.intensity * 10}%`, backgroundColor: item.intensity >= 8 ? getCategoryColor(item.category) : undefined }} />
                </div>
              </div>

              <div className="bg-slate-50 border border-slate-100 rounded-xl p-4 mt-4">
                <p className="text-[9px] font-bold text-slate-400 uppercase mb-2 flex items-center gap-1">
                  <Target className="w-3 h-3" /> Evidência
                </p>
                <p className="text-xs text-slate-700 font-medium mb-2 leading-relaxed italic">"{item.evidence}"</p>
                <div className="pt-2 border-t border-slate-200/50">
                   <p className="text-[11px] text-slate-500 leading-relaxed">
                     <span className="font-bold text-slate-600">Cognição:</span> {item.analysis}
                   </p>
                </div>
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Supporting Texts Section (Textos de Apoio) */}
      {data.supportingTexts && data.supportingTexts.length > 0 && (
        <div className="bg-white border-2 border-slate-100 rounded-[2.5rem] p-8 shadow-xl">
          <div className="flex items-center gap-3 mb-8">
            <div className="p-2 rounded-xl bg-indigo-600 text-white">
              <FileText className="w-5 h-5" />
            </div>
            <div>
              <h3 className="text-lg font-black text-slate-900 tracking-tight">Textos de Apoio Gerados</h3>
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Ativos prontos para implementação</p>
            </div>
          </div>

          <div className="space-y-10">
            {data.supportingTexts.map((section, idx) => (
              <div key={idx} className="space-y-4">
                <div className="flex items-center gap-2 border-b border-slate-50 pb-2">
                  <ChevronRight className="w-4 h-4 text-indigo-500" />
                  <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">{section.label}</h4>
                </div>
                <div className="grid grid-cols-1 gap-3">
                  {section.items.map((item, i) => (
                    <div key={i} className="group flex items-center justify-between bg-slate-50 hover:bg-white p-4 rounded-2xl border border-slate-100 hover:border-indigo-200 hover:shadow-md transition-all">
                      <p className="text-sm font-bold text-slate-800 leading-relaxed pr-8">{item}</p>
                      <button 
                        onClick={() => copyToClipboard(item)}
                        className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all flex-shrink-0"
                        title="Copiar texto"
                      >
                        <Copy className="w-4 h-4" />
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Suggested Alternative Copys (High Intensity Variations) */}
      {data.suggestedCopys && data.suggestedCopys.length > 0 && (
        <div className={`bg-white border-2 rounded-[2.5rem] p-8 shadow-xl transition-all ${hasLowIntensity ? 'border-amber-200 shadow-amber-50' : 'border-indigo-100 shadow-indigo-50'}`}>
          <div className="flex items-center justify-between mb-8">
            <div className="flex items-center gap-3">
              <div className={`p-2 rounded-xl ${hasLowIntensity ? 'bg-amber-100 text-amber-600' : 'bg-indigo-100 text-indigo-600'}`}>
                <Zap className="w-5 h-5" />
              </div>
              <div>
                <h3 className="text-lg font-black text-slate-900 tracking-tight">Variações Estratégicas</h3>
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                  {hasLowIntensity 
                    ? `Otimizações focadas em elevar intensidade` 
                    : 'Upgrade para Performance Máxima'
                  }
                </p>
              </div>
            </div>
          </div>

          <div className="space-y-6">
            {data.suggestedCopys.map((copy, idx) => (
              <div key={idx} className="group bg-slate-50 hover:bg-white border border-slate-100 hover:border-indigo-200 hover:shadow-lg rounded-2xl p-6 transition-all relative overflow-hidden">
                <div className="absolute top-0 right-0 p-3 opacity-0 group-hover:opacity-100 transition-opacity">
                   <button onClick={() => copyToClipboard(copy.text)} className="bg-slate-900 text-white p-2 rounded-lg shadow-lg hover:bg-slate-800 active:scale-90 transition-all">
                      <Copy className="w-4 h-4" />
                   </button>
                </div>
                <div className="flex items-center gap-2 mb-3">
                   <span className="text-[9px] font-black uppercase tracking-widest px-2 py-0.5 rounded border bg-indigo-50 text-indigo-500 border-indigo-100">
                     Foco: {copy.trigger}
                   </span>
                </div>
                <blockquote className="text-sm font-bold text-slate-800 leading-relaxed mb-4 italic border-l-4 border-indigo-500 pl-4 py-1">
                  "{copy.text}"
                </blockquote>
                <div className="flex items-start gap-2 bg-white/50 p-3 rounded-xl border border-slate-100">
                   <MessageSquareQuote className="w-3.5 h-3.5 text-slate-400 mt-0.5 flex-shrink-0" />
                   <p className="text-[11px] text-slate-500 font-medium italic">
                     <span className="text-slate-700 font-bold not-italic">Raciocínio:</span> {copy.reasoning}
                   </p>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Suggested CTAs Section */}
      {data.suggestedCTAs && data.suggestedCTAs.length > 0 && (
        <div className="bg-white border border-slate-200 rounded-3xl p-6 shadow-sm">
          <div className="flex items-center gap-2 mb-4">
            <MousePointerClick className="text-indigo-600 w-4 h-4" />
            <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Sugestões de CTA</h4>
          </div>
          <div className="flex flex-wrap gap-3">
            {data.suggestedCTAs.map((cta, idx) => (
              <button
                key={idx}
                onClick={() => copyToClipboard(cta)}
                className="flex items-center gap-2 px-4 py-2.5 bg-slate-50 border border-slate-100 rounded-xl text-xs font-bold text-slate-700 hover:border-indigo-200 hover:bg-indigo-50 transition-all group"
              >
                <span>{cta}</span>
                <Copy className="w-3 h-3 text-slate-300 group-hover:text-indigo-400" />
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Optimizations Section */}
      <div className="bg-slate-900 rounded-3xl p-8 text-white shadow-xl shadow-indigo-100">
        <div className="flex items-center gap-2 mb-6">
          <TrendingUp className="text-emerald-400 w-5 h-5" />
          <h3 className="text-lg font-bold tracking-tight">Oportunidades de Performance</h3>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {data.improvements.map((item, i) => (
            <div key={i} className="flex gap-3 bg-white/5 p-4 rounded-2xl border border-white/10">
              <CheckCircle2 className="w-5 h-5 text-emerald-400 flex-shrink-0" />
              <p className="text-xs leading-relaxed text-slate-200">{item}</p>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default ResultDisplay;

import React, { useState, useRef, useEffect } from 'react';
import { analyzeCreative } from './services/geminiService';
import { AnalysisResult, AnalysisStatus, Brand, BRANDS, Platform, PLATFORMS } from './types';
import ResultDisplay from './components/ResultDisplay';
import TriggersModal from './components/TriggersModal';
import DesignerArea from './components/DesignerArea';
import { 
  Sparkles, 
  AlertTriangle, 
  Loader2, 
  BrainCircuit, 
  BookOpen, 
  ChevronDown, 
  Check, 
  Globe, 
  User, 
  ExternalLink,
  Facebook,
  Search,
  Layout,
  Video,
  PenTool,
  Palette,
  LayoutGrid
} from 'lucide-react';

type AppArea = 'redator' | 'designer';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean | null>(null);
  const [activeArea, setActiveArea] = useState<AppArea>('redator');
  const [copyText, setCopyText] = useState('');
  const [platform, setPlatform] = useState<Platform>('Meta Padrão');
  const [status, setStatus] = useState<AnalysisStatus>(AnalysisStatus.IDLE);
  const [result, setResult] = useState<AnalysisResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isBrandMenuOpen, setIsBrandMenuOpen] = useState(false);
  const [isPlatformMenuOpen, setIsPlatformMenuOpen] = useState(false);
  const [selectedBrand, setSelectedBrand] = useState<Brand>('Anhanguera');

  const brandMenuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const checkAuth = async () => {
      // @ts-ignore
      if (window.aistudio && typeof window.aistudio.hasSelectedApiKey === 'function') {
        try {
          // @ts-ignore
          const hasKey = await window.aistudio.hasSelectedApiKey();
          setIsAuthenticated(hasKey);
        } catch {
          setIsAuthenticated(false);
        }
      } else {
        setIsAuthenticated(!!process.env.API_KEY);
      }
    };
    checkAuth();
  }, []);

  const handleOpenKeySelector = async () => {
    // @ts-ignore
    if (window.aistudio && typeof window.aistudio.openSelectKey === 'function') {
      // @ts-ignore
      await window.aistudio.openSelectKey();
      setIsAuthenticated(true);
    }
  };

  const handleAnalyze = async () => {
    if (!copyText.trim()) {
      setError("Por favor, insira o texto da peça para análise.");
      return;
    }

    setStatus(AnalysisStatus.LOADING);
    setError(null);
    setResult(null);

    try {
      const data = await analyzeCreative(copyText, platform);
      setResult(data);
      setStatus(AnalysisStatus.SUCCESS);
    } catch (err: any) {
      console.error("Analisador Error:", err);
      setError("Falha na análise. Tente novamente.");
      setStatus(AnalysisStatus.ERROR);
    }
  };

  if (isAuthenticated === null) {
    return (
      <div className="min-h-screen bg-white flex flex-col items-center justify-center p-12 text-center">
        <Loader2 className="w-10 h-10 text-indigo-600 animate-spin mb-4" />
        <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">Verificando Credenciais...</p>
      </div>
    );
  }

  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-6">
        <div className="max-w-md w-full bg-white rounded-[2.5rem] shadow-2xl border border-slate-100 p-12 text-center relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-1.5 bg-indigo-600" />
          <div className="w-20 h-20 bg-indigo-600 rounded-3xl flex items-center justify-center mx-auto mb-10 shadow-xl shadow-indigo-100">
            <BrainCircuit className="text-white w-10 h-10" />
          </div>
          <h1 className="text-3xl font-black text-slate-900 mb-4 tracking-tighter">Creative AI</h1>
          <p className="text-slate-500 font-medium mb-12 leading-relaxed text-sm">
            Para utilizar o analisador de gatilhos, é necessário selecionar uma conta Google válida.
          </p>
          <button onClick={handleOpenKeySelector} className="w-full bg-slate-900 text-white py-4 rounded-2xl flex items-center justify-center gap-4 hover:bg-slate-800 transition-all shadow-lg font-bold text-sm">
            Conectar com Google
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900 flex flex-col">
      <header className="bg-white/90 backdrop-blur-md border-b border-slate-100 sticky top-0 z-40">
        <div className="max-w-7xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-8">
            <div className="flex items-center gap-3">
              <div className="bg-indigo-600 p-2 rounded-xl shadow-lg shadow-indigo-100">
                <BrainCircuit className="text-white w-5 h-5" />
              </div>
              <h1 className="text-lg font-black tracking-tighter hidden md:block">Creative Analyzer</h1>
            </div>

            <nav className="flex items-center bg-slate-100/50 p-1 rounded-2xl border border-slate-100">
              <button 
                onClick={() => setActiveArea('redator')}
                className={`flex items-center gap-2 px-5 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeArea === 'redator' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
              >
                <PenTool className="w-3.5 h-3.5" />
                Área do Redator
              </button>
              <button 
                onClick={() => setActiveArea('designer')}
                className={`flex items-center gap-2 px-5 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeArea === 'designer' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
              >
                <Palette className="w-3.5 h-3.5" />
                Área do Designer
              </button>
            </nav>
          </div>

          <div className="flex items-center gap-3">
            <button onClick={() => setIsModalOpen(true)} className="flex items-center gap-2 px-3 py-2 text-slate-600 hover:bg-slate-100 rounded-xl transition-all font-bold text-[10px] uppercase tracking-widest">
              <BookOpen className="w-4 h-4 text-indigo-600" />
              Gatilhos
            </button>
            <div className="relative">
              <button onClick={() => setIsBrandMenuOpen(!isBrandMenuOpen)} className={`flex items-center gap-2 px-4 py-2 rounded-xl transition-all font-bold text-[10px] uppercase border tracking-widest ${isBrandMenuOpen ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-slate-50 text-slate-600 border-slate-100'}`}>
                <Globe className="w-3.5 h-3.5" />
                <span>{selectedBrand}</span>
                <ChevronDown className={`w-3 h-3 transition-transform ${isBrandMenuOpen ? 'rotate-180' : ''}`} />
              </button>
              {isBrandMenuOpen && (
                <div className="absolute right-0 mt-2 w-56 bg-white border border-slate-100 rounded-2xl shadow-xl py-2 z-50">
                  {BRANDS.map(brand => (
                    <button key={brand} onClick={() => { setSelectedBrand(brand); setIsBrandMenuOpen(false); }} className={`w-full px-4 py-2.5 text-left text-[11px] font-bold hover:bg-slate-50 ${selectedBrand === brand ? 'text-indigo-600 bg-indigo-50/50' : 'text-slate-600'}`}>
                      {brand}
                    </button>
                  ))}
                </div>
              )}
            </div>
            <button onClick={handleOpenKeySelector} className="w-9 h-9 bg-slate-100 rounded-full flex items-center justify-center border border-slate-200 hover:border-indigo-400 transition-all group relative">
              <User className="w-5 h-5 text-slate-500 group-hover:text-indigo-600" />
            </button>
          </div>
        </div>
      </header>

      {activeArea === 'redator' ? (
        <main className="flex-grow max-w-7xl mx-auto w-full px-6 py-10 grid grid-cols-1 xl:grid-cols-12 gap-10">
          <div className="xl:col-span-5 space-y-6">
            <div className="bg-white rounded-[2rem] p-8 shadow-sm border border-slate-100 sticky top-24">
              <div className="mb-8">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 block">Texto da Peça (Criativo)</label>
                <textarea 
                  className="w-full bg-slate-50 border border-slate-100 rounded-2xl p-5 text-sm focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-600 outline-none transition-all min-h-[200px]" 
                  placeholder="Cole aqui o texto da imagem, vídeo ou anúncio..." 
                  value={copyText} 
                  onChange={(e) => setCopyText(e.target.value)} 
                />
              </div>

              <div className="pt-6 border-t border-slate-50 space-y-5">
                <div className="relative">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 block">Configuração de Canal e Apoio</label>
                  <button 
                    onClick={() => setIsPlatformMenuOpen(!isPlatformMenuOpen)}
                    className="w-full flex items-center justify-between px-5 py-4 bg-slate-50 border border-slate-100 rounded-2xl font-bold text-[11px] uppercase tracking-wider text-slate-700 hover:border-indigo-300 transition-all"
                  >
                    <div className="flex items-center gap-3">
                      <LayoutGrid className="w-4 h-4 text-indigo-600" />
                      <span>{platform}</span>
                    </div>
                    <ChevronDown className={`w-4 h-4 transition-transform ${isPlatformMenuOpen ? 'rotate-180' : ''}`} />
                  </button>

                  {isPlatformMenuOpen && (
                    <div className="absolute left-0 bottom-full mb-2 w-full bg-white border border-slate-100 rounded-2xl shadow-2xl py-2 z-50 max-h-[300px] overflow-y-auto">
                      {PLATFORMS.map(p => (
                        <button key={p} onClick={() => { setPlatform(p); setIsPlatformMenuOpen(false); }} className={`w-full px-5 py-3 text-left text-[10px] font-black uppercase tracking-widest hover:bg-slate-50 flex items-center justify-between ${platform === p ? 'text-indigo-600 bg-indigo-50' : 'text-slate-500'}`}>
                          {p}
                          {platform === p && <Check className="w-3 h-3" />}
                        </button>
                      ))}
                    </div>
                  )}
                </div>

                {error && (
                  <div className="p-4 bg-red-50 border border-red-100 rounded-xl text-red-600 text-[11px] font-bold flex gap-2">
                    <AlertTriangle className="w-4 h-4 flex-shrink-0" />
                    <span>{error}</span>
                  </div>
                )}

                <button 
                  onClick={handleAnalyze} 
                  disabled={status === AnalysisStatus.LOADING || !copyText.trim()} 
                  className={`w-full py-5 rounded-2xl font-black text-xs uppercase tracking-[0.2em] flex items-center justify-center gap-3 transition-all active:scale-[0.98] shadow-xl ${status === AnalysisStatus.LOADING || !copyText.trim() ? 'bg-slate-100 text-slate-400' : 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-indigo-100'}`}
                >
                  {status === AnalysisStatus.LOADING ? <Loader2 className="w-5 h-5 animate-spin" /> : <><Sparkles className="w-5 h-5" /> Analisar e Gerar Apoio</>}
                </button>
              </div>
            </div>
          </div>

          <div className="xl:col-span-7">
            {status === AnalysisStatus.IDLE && (
              <div className="h-full min-h-[400px] flex flex-col items-center justify-center text-center p-12 bg-white/50 rounded-[3rem] border-2 border-dashed border-slate-200">
                <BrainCircuit className="w-16 h-16 text-slate-100 mb-6" />
                <h3 className="text-sm font-black text-slate-300 uppercase tracking-[0.4em]">Aguardando Texto</h3>
                <p className="text-slate-400 mt-4 text-[11px] font-bold uppercase tracking-widest max-w-xs leading-relaxed">Insira sua copy para extrair o diagnóstico e os textos de apoio.</p>
              </div>
            )}
            {status === AnalysisStatus.LOADING && (
              <div className="h-full flex flex-col items-center justify-center text-center p-12 animate-in fade-in duration-500">
                <div className="relative mb-10">
                  <div className="w-24 h-24 border-8 border-slate-100 border-t-indigo-600 rounded-full animate-spin"></div>
                  <div className="absolute inset-0 flex items-center justify-center"><Sparkles className="w-8 h-8 text-indigo-600 animate-pulse" /></div>
                </div>
                <h3 className="text-xl font-black text-slate-800 tracking-tight uppercase">Processando...</h3>
                <p className="text-slate-500 text-[10px] mt-2 font-bold uppercase tracking-widest">Extraindo gatilhos e gerando ativos</p>
              </div>
            )}
            {status === AnalysisStatus.SUCCESS && result && <ResultDisplay data={result} />}
          </div>
        </main>
      ) : (
        <DesignerArea selectedBrand={selectedBrand} />
      )}

      <TriggersModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} />
    </div>
  );
};

export default App;

import React from 'react';
