              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  trigger: { type: Type.STRING },
                  category: { type: Type.STRING },
                  text: { type: Type.STRING },
                  reasoning: { type: Type.STRING }
                },
                required: ["trigger", "category", "text", "reasoning"]
              }
            },
            supportingTexts: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  label: { type: Type.STRING },
                  items: { type: Type.ARRAY, items: { type: Type.STRING } },
                  limit: { type: Type.NUMBER }
                },
                required: ["label", "items"]
              }
            },
            improvements: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["score", "summary", "foundItems", "improvements", "suggestedCTAs", "suggestedCopys", "supportingTexts"]
        }
      }
    });

    const responseText = response.text;
    if (!responseText) throw new Error("A IA não conseguiu gerar uma resposta válida.");

    return JSON.parse(responseText.trim()) as AnalysisResult;
  } catch (apiError: any) {
    console.error("Erro na chamada da Gemini API:", apiError);
    throw apiError;
  }
};

import React from 'react';
import { AnalysisResult } from '../types';
import { 
  CheckCircle2, 
  Target, 
  TrendingUp, 
  Info, 
  Layers, 
  Copy, 
  MousePointerClick, 
  Zap, 
  MessageSquareQuote, 
  AlertCircle, 
  FileText, 
  ChevronRight, 
  CopyPlus,
  ClipboardCheck,
  ClipboardList
} from 'lucide-react';

interface Props {
  data: AnalysisResult;
}

const ResultDisplay: React.FC<Props> = ({ data }) => {
  const getCategoryColor = (cat: string) => {
    const c = cat.toLowerCase();
    if (c.includes('performance') && c.includes('atributo')) return '#0ea5e9';
    if (c.includes('performance')) return '#38bdf8';
    if (c.includes('oferta')) return '#4ade80';
    if (c.includes('atributo')) return '#f472b6';
    return '#6366f1';
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
  };

  const copyAllFromSection = (label: string, items: string[]) => {
    const header = `--- ${label} ---`;
    const formattedItems = items.map((item, index) => `${index + 1}. ${item}`).join('\n');
    const finalContent = `${header}\n${formattedItems}`;

    navigator.clipboard.writeText(finalContent);
    alert(`Bloco "${label}" copiado com sucesso!`);
  };

  const copyAllSupportingTexts = () => {
    if (!data.supportingTexts || data.supportingTexts.length === 0) return;

    const allContent = data.supportingTexts.map(section => {
      const header = `[ ${section.label} ]`;
      const body = section.items.map((item, i) => `${i + 1}. ${item}`).join('\n');
      return `${header}\n${body}`;
    }).join('\n\n');

    const finalExport = `DIAGNÓSTICO E ATIVOS GERADOS\nEficácia: ${data.score}/100\n\n${allContent}`;

